 48	    /// <summary>
 49	    /// One entry per row of the Clearance Readiness checklist.
 50	    ///
 51	    /// AutoSource marks the checks this app can answer from its own data today. The
 52	    /// other six describe a resignation-approval and exit-clearance module that does
 53	    /// not exist yet, so HR ticks them by hand for now - which is the correct
 54	    /// behaviour rather than a gap: the point of the checklist is that a human
 55	    /// confirms the data is complete before payroll calculates on it.
 56	    /// </summary>
 57	    public sealed class ReadinessCheck
 58	    {
