98	    98	            FROM   dbo.HR_FNFSettlement WITH (UPDLOCK, HOLDLOCK)
99	    99	            WHERE  CaseNo LIKE @Prefix + '[0-9][0-9][0-9][0-9][0-9]'", conn, tx))
100	   100	        {
