141	   141	            object value = cmd.ExecuteScalar();
142	   142	            required = (value == null || value == DBNull.Value) || Convert.ToInt32(value) == 1;
143	   143	        }
144	   144	
145	   145	        if (!required) return string.Empty;
146	   146	
147	   147	        return @"
148	   148	              AND EXISTS (SELECT 1 FROM dbo.HR_ExitFormality X
149	   149	                          WHERE  X.EmployeeMasterID = EM.EmployeeMasterID
150	   150	                            AND  X.Status = 1
151	   151	                            AND  X.IsComplete = 1) ";
