158	   158	    {
159	   159	        const string sql = @"
160	   160	            SELECT EM.EmployeeMasterID,
161	   161	                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FatherName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.LastName)),''), ''))
162	   162	                       + ' (' + ISNULL(EM.Code, '') + ')' AS Name
163	   163	            FROM   dbo.HR_EmployeeMaster EM
164	   164	            WHERE  EM.Status = 1
165	   165	              AND  EM.CompanyMasterID = @CompanyID
166	   166	              AND  ( (EM.ResignDate IS NOT NULL AND EM.ResignDate > @Epoch)
167	   167	                  OR (EM.DateOfLeft IS NOT NULL AND EM.DateOfLeft > @Epoch) )
168	   168	              AND  NOT EXISTS (SELECT 1 FROM dbo.HR_FNFSettlement F
169	   169	                               WHERE  F.EmployeeMasterID = EM.EmployeeMasterID
170	   170	                                 AND  F.Status = 1
171	   171	                                 AND  F.WorkflowStatus <> @Cancelled)";
172	   172	
173	   173	        // Exit Formality must be complete first, when the company requires it. Appended
174	   174	        // because it references tables a tenant database may not have yet.
175	   175	        string gated = sql + ExitFormalityGate(conn, tx, companyId) + " ORDER BY EM.Code";
176	   176	
