193	   193	    /// <summary>
194	   194	    /// Creates the case, copies the employee snapshot, seeds the readiness checklist,
195	   195	    /// auto-answers the checks this app can answer, discovers the recoveries it can
196	   196	    /// see, and evaluates the clearance verdict.
197	   197	    ///
198	   198	    /// The CALLER owns the transaction - all six steps must commit together or a case
199	   199	    /// exists with a half-built checklist, and a caller-owned transaction is also what
200	   200	    /// makes this testable against the live database without writing to it.
201	   201	    /// </summary>
202	   202	    public static long CreateCase(SqlConnection conn, SqlTransaction tx, long employeeId,
203	   203	                                  long companyId, int userId, string systemName,
204	   204	                                  int complianceWindowDays)
205	   205	    {
