208	   208	
209	   209	        {
210	   210	            {
211	   211	                DateTime caseDate = DateTime.Today;
212	   212	                string caseNo = NextCaseNo(conn, tx, caseDate.Year);
213	   213	                long caseId;
214	   214	
215	   215	                // The snapshot is taken from the employee here and never re-read: a
216	   216	                // later transfer or re-designation must not change what was settled.
217	   217	                using (var cmd = new SqlCommand(@"
218	   218	                    INSERT INTO dbo.HR_FNFSettlement
219	   219	                        (CaseNo, EmployeeMasterID, CaseDate, CasePriority, WorkflowStatus,
220	   220	                         ResignDate, LastWorkingDate, DateOfJoining,
221	   221	                         DepartmentMasterID, DesignationMasterID, ReportingPersonID,
222	   222	                         NoticeDaysRequired,
223	   223	                         CategoryMasterID, BranchMasterID, CompanyMasterID,
224	   224	                         ComplianceWindowDays, Status,
225	   225	                         EntryUserMasterID, EntryUserDateTime, SystemName)
226	   226	                    SELECT @CaseNo, EM.EmployeeMasterID, @CaseDate, 'Normal', @Draft,
227	   227	                           NULLIF(EM.ResignDate, @Epoch), NULLIF(EM.DateOfLeft, @Epoch),
228	   228	                           NULLIF(EM.DateOfJoining, @Epoch),
229	   229	                           EM.DepartmentMasterID, EM.DesignationMasterID, EM.ReportingPersonID,
230	   230	                           EM.NoticePeriodDays,
231	   231	                           EM.CategoryMasterID, EM.BranchMasterID, @CompanyID,
232	   232	                           @WindowDays, 1,
233	   233	                           @UserID, GETDATE(), @SystemName
234	   234	                    FROM   dbo.HR_EmployeeMaster EM
235	   235	                    WHERE  EM.EmployeeMasterID = @EmpID;
236	   236	                    SELECT CAST(SCOPE_IDENTITY() AS bigint);", conn, tx))
237	   237	                {
238	   238	                    cmd.Parameters.AddWithValue("@CaseNo", caseNo);
239	   239	                    cmd.Parameters.AddWithValue("@CaseDate", caseDate);
240	   240	                    cmd.Parameters.AddWithValue("@Draft", StatusDraft);
241	   241	                    cmd.Parameters.AddWithValue("@Epoch", EpochDate);
242	   242	                    cmd.Parameters.AddWithValue("@CompanyID", companyId);
243	   243	                    cmd.Parameters.AddWithValue("@WindowDays", complianceWindowDays);
244	   244	                    cmd.Parameters.AddWithValue("@UserID", userId);
245	   245	                    cmd.Parameters.AddWithValue("@SystemName", Trunc(systemName, 50));
246	   246	                    cmd.Parameters.AddWithValue("@EmpID", employeeId);
247	   247	
248	   248	                    object idObj = cmd.ExecuteScalar();
249	   249	                    if (idObj == null || idObj == DBNull.Value)
250	   250	                        throw new InvalidOperationException(
251	   251	                            "Employee " + employeeId + " was not found, so no F&F case was created.");
252	   252	
