269	   269	    /// re-seed must never wipe an answer somebody already gave.
270	   270	    /// </summary>
271	   271	    public static int SeedReadiness(SqlConnection conn, SqlTransaction tx, long caseId)
272	   272	    {
273	   273	        int added = 0;
274	   274	
275	   275	        foreach (ReadinessCheck chk in ReadinessTemplate())
276	   276	        {
277	   277	            using (var cmd = new SqlCommand(@"
278	   278	                INSERT INTO dbo.HR_FNFCheck
279	   279	                    (FNFSettlementID, CheckKind, CheckCode, CheckName, IsRequired, SortOrder)
280	   280	                SELECT @CaseID, @Kind, @Code, @Name, @Req, @Sort
281	   281	                WHERE  NOT EXISTS (SELECT 1 FROM dbo.HR_FNFCheck
282	   282	                                   WHERE FNFSettlementID = @CaseID
283	   283	                                     AND CheckKind = @Kind
