299	   299	    /// <summary>
300	   300	    /// Answers the three checks this app has data for, and only those.
301	   301	    ///
302	   302	    ///   LEAVE_BAL  - does the employee have leave rows at all? An objective
303	   303	    ///                existence test; the remark carries the balance so the human
304	   304	    ///                can sanity-check it.
305	   305	    ///   ATT_FINAL  - is there an HR_MonthlyAttendance row for the last working
306	   306	    ///                month? This is the one that genuinely gates the calculation.
307	   307	    ///   LOAN_LEDGER- deliberately left for Finance to tick. Whether a ledger is
308	   308	    ///                "updated" is a judgement, not a query. The outstanding figure
309	   309	    ///                goes in the remark so they are ticking something informed.
310	   310	    ///
311	   311	    /// Never overwrites an answer a person has already given.
312	   312	    /// </summary>
313	   313	    public static void AutoAnswerReadiness(SqlConnection conn, SqlTransaction tx, long caseId)
314	   314	    {
315	   315	        // --- Leave balance ---------------------------------------------------
316	   316	        using (var cmd = new SqlCommand(@"
317	   317	            UPDATE C
318	   318	            SET    C.Result  = CASE WHEN L.LeaveRows > 0 THEN 'Yes' ELSE 'No' END,
319	   319	                   C.Remarks = CASE WHEN L.LeaveRows > 0
320	   320	                                    THEN CAST(L.LeaveRows AS varchar(10)) + ' leave type(s), balance '
321	   321	                                         + CAST(CAST(ISNULL(L.TotalBalance,0) AS decimal(18,2)) AS varchar(20))
322	   322	                                    ELSE 'No leave rows found for this employee.' END,
323	   323	                   C.ActionedOn = GETDATE()
324	   324	            FROM   dbo.HR_FNFCheck C
325	   325	            INNER  JOIN dbo.HR_FNFSettlement F ON F.FNFSettlementID = C.FNFSettlementID
326	   326	            CROSS  APPLY (SELECT COUNT(*) AS LeaveRows, SUM(EWL.Balance) AS TotalBalance
327	   327	                          FROM   dbo.HR_EmployeeWiseLeave EWL
328	   328	                          WHERE  EWL.EmployeeMasterID = F.EmployeeMasterID
329	   329	                            AND  ISNULL(EWL.IsActive, 1) = 1) L
330	   330	            WHERE  C.FNFSettlementID = @CaseID
331	   331	              AND  C.CheckKind = @Kind
332	   332	              AND  C.CheckCode = 'LEAVE_BAL'
333	   333	              AND  C.Result IS NULL", conn, tx))
334	   334	        {
335	   335	            cmd.Parameters.AddWithValue("@CaseID", caseId);
336	   336	            cmd.Parameters.AddWithValue("@Kind", KindReadiness);
337	   337	            cmd.ExecuteNonQuery();
338	   338	        }
339	   339	
340	   340	        // --- Attendance finalized till LWD -----------------------------------
341	   341	        // No last working day yet means the question cannot be answered at all -
342	   342	        // left unanswered rather than failed, so the reason shown is the missing
343	   343	        // date rather than a misleading "attendance not done".
344	   344	        using (var cmd = new SqlCommand(@"
345	   345	            UPDATE C
346	   346	            SET    C.Result  = CASE WHEN F.LastWorkingDate IS NULL THEN NULL
347	   347	                                    WHEN A.Rows > 0 THEN 'Yes' ELSE 'No' END,
348	   348	                   C.Remarks = CASE WHEN F.LastWorkingDate IS NULL
349	   349	                                    THEN 'Last working day is not set on the employee yet.'
350	   350	                                    WHEN A.Rows > 0
351	   351	                                    THEN 'Monthly attendance confirmed for '
352	   352	                                         + RIGHT('00' + CAST(MONTH(F.LastWorkingDate) AS varchar(2)), 2) + '/'
353	   353	                                         + CAST(YEAR(F.LastWorkingDate) AS varchar(4))
354	   354	                                    ELSE 'No HR_MonthlyAttendance row for '
355	   355	                                         + RIGHT('00' + CAST(MONTH(F.LastWorkingDate) AS varchar(2)), 2) + '/'
356	   356	                                         + CAST(YEAR(F.LastWorkingDate) AS varchar(4))
357	   357	                                         + ' - run Confirm Pay for the final month first.' END,
358	   358	                   C.ActionedOn = GETDATE()
359	   359	            FROM   dbo.HR_FNFCheck C
360	   360	            INNER  JOIN dbo.HR_FNFSettlement F ON F.FNFSettlementID = C.FNFSettlementID
361	   361	            CROSS  APPLY (SELECT COUNT(*) AS Rows
362	   362	                          FROM   dbo.HR_MonthlyAttendance MA
363	   363	                          WHERE  MA.EmployeeMasterID = F.EmployeeMasterID
364	   364	                            AND  F.LastWorkingDate IS NOT NULL
365	   365	                            AND  MA.AttendMonth = MONTH(F.LastWorkingDate)
366	   366	                            AND  MA.AttendYear  = YEAR(F.LastWorkingDate)) A
367	   367	            WHERE  C.FNFSettlementID = @CaseID
368	   368	              AND  C.CheckKind = @Kind
369	   369	              AND  C.CheckCode = 'ATT_FINAL'
370	   370	              AND  C.Result IS NULL", conn, tx))
371	   371	        {
372	   372	            cmd.Parameters.AddWithValue("@CaseID", caseId);
373	   373	            cmd.Parameters.AddWithValue("@Kind", KindReadiness);
374	   374	            cmd.ExecuteNonQuery();
375	   375	        }
376	   376	
377	   377	        // --- Loan ledger: informational remark only, no verdict --------------
378	   378	        using (var cmd = new SqlCommand(@"
379	   379	            UPDATE C
380	   380	            SET    C.Remarks = 'Outstanding from unpaid EMI schedule: '
381	   381	                             + CAST(CAST(ISNULL(O.Outstanding,0) AS decimal(18,2)) AS varchar(20))
382	   382	                             + '. Finance to confirm the ledger is up to date.'
383	   383	            FROM   dbo.HR_FNFCheck C
384	   384	            INNER  JOIN dbo.HR_FNFSettlement F ON F.FNFSettlementID = C.FNFSettlementID
385	   385	            CROSS  APPLY (SELECT SUM(S.EMIAmount) AS Outstanding
386	   386	                          FROM   dbo.HR_LoanEMISchedule S
387	   387	                          WHERE  S.EmployeeMasterID = F.EmployeeMasterID
388	   388	                            AND  S.IsPaid = 0
389	   389	                            AND  S.Status = 1) O
390	   390	            WHERE  C.FNFSettlementID = @CaseID
391	   391	              AND  C.CheckKind = @Kind
392	   392	              AND  C.CheckCode = 'LOAN_LEDGER'
393	   393	              AND  C.Result IS NULL", conn, tx))
394	   394	        {
395	   395	            cmd.Parameters.AddWithValue("@CaseID", caseId);
396	   396	            cmd.Parameters.AddWithValue("@Kind", KindReadiness);
397	   397	            cmd.ExecuteNonQuery();
398	   398	        }
399	   399	    }
