405	   405	    /// <summary>
406	   406	    /// Writes the recovery rows this app can find by itself: the unpaid loan / advance
407	   407	    /// schedule, and every asset the employee still holds.
408	   408	    ///
409	   409	    /// Guarded by NOT EXISTS on the same (case, department, dues type, source id), so
410	   410	    /// re-running after an asset is returned adds nothing and - importantly - does not
411	   411	    /// resurrect a row somebody Waived.
412	   412	    ///
413	   413	    /// Asset balance follows the module's own rule: QtyIssued minus the quantity
414	   414	    /// returned on ACTIVE returns, counting only approved issues. Never IsReturned,
415	   415	    /// which is a derived cache.
416	   416	    /// </summary>
417	   417	    public static int DiscoverRecoveries(SqlConnection conn, SqlTransaction tx, long caseId,
418	   418	                                         int userId, string systemName)
419	   419	    {
420	   420	        int added = 0;
421	   421	
422	   422	        // --- Loan / advance outstanding --------------------------------------
423	   423	        using (var cmd = new SqlCommand(@"
424	   424	            INSERT INTO dbo.HR_FNFRecovery
425	   425	                (FNFSettlementID, ClearanceDepartment, DuesType, Description, Amount,
426	   426	                 RecoveryStatus, Status, EntryUserMasterID, EntryUserDateTime, SystemName)
427	   427	            SELECT @CaseID, 'Finance', 'Loan',
428	   428	                   'Unpaid loan / advance installments (' + CAST(O.Cnt AS varchar(10)) + ')',
429	   429	                   O.Outstanding, 'Confirmed', 1, @UserID, GETDATE(), @SystemName
430	   430	            FROM   dbo.HR_FNFSettlement F
431	   431	            CROSS  APPLY (SELECT COUNT(*) AS Cnt, SUM(S.EMIAmount) AS Outstanding
432	   432	                          FROM   dbo.HR_LoanEMISchedule S
433	   433	                          WHERE  S.EmployeeMasterID = F.EmployeeMasterID
434	   434	                            AND  S.IsPaid = 0
435	   435	                            AND  S.Status = 1) O
436	   436	            WHERE  F.FNFSettlementID = @CaseID
437	   437	              AND  O.Outstanding > 0
438	   438	              AND  NOT EXISTS (SELECT 1 FROM dbo.HR_FNFRecovery R
439	   439	                               WHERE R.FNFSettlementID = @CaseID
440	   440	                                 AND R.DuesType = 'Loan'
441	   441	                                 AND R.AssetIssueDetailID IS NULL);", conn, tx))
442	   442	        {
443	   443	            cmd.Parameters.AddWithValue("@CaseID", caseId);
444	   444	            cmd.Parameters.AddWithValue("@UserID", userId);
445	   445	            cmd.Parameters.AddWithValue("@SystemName", Trunc(systemName, 50));
446	   446	            added += cmd.ExecuteNonQuery();
447	   447	        }
448	   448	
449	   449	        // --- Assets still held ------------------------------------------------
450	   450	        // Amount is left at 0 on purpose: what an unreturned laptop is worth is a
451	   451	        // human decision, and putting a guessed figure into a settlement is worse
452	   452	        // than leaving it for someone to fill in.
453	   453	        using (var cmd = new SqlCommand(@"
454	   454	            INSERT INTO dbo.HR_FNFRecovery
455	   455	                (FNFSettlementID, ClearanceDepartment, DuesType, Description, Amount,
456	   456	                 RecoveryStatus, AssetItemID, AssetIssueDetailID,
457	   457	                 Status, EntryUserMasterID, EntryUserDateTime, SystemName)
458	   458	            SELECT @CaseID, 'IT', 'Asset Not Returned',
459	   459	                   ISNULL(AID.AssetName, '')
460	   460	                     + CASE WHEN ISNULL(AID.SerialNo,'') <> '' THEN ' [' + AID.SerialNo + ']' ELSE '' END
461	   461	                     + ' - outstanding qty ' + CAST(Bal.Balance AS varchar(20))
462	   462	                     + ' (issue ' + ISNULL(AI.IssueNo,'') + ')',
463	   463	                   0, 'Confirmed', AID.AssetItemID, AID.ID,
464	   464	                   1, @UserID, GETDATE(), @SystemName
465	   465	            FROM   dbo.HR_FNFSettlement F
466	   466	            INNER  JOIN dbo.HR_AssetIssue AI
467	   467	                   ON  AI.EmployeeMasterID = F.EmployeeMasterID
468	   468	                   AND AI.Status = 1
469	   469	                   AND AI.ApprovalStatus = 'Approved'
470	   470	            INNER  JOIN dbo.HR_AssetIssueDetail AID ON AID.IssueID = AI.ID
471	   471	            CROSS  APPLY (SELECT ISNULL(AID.QtyIssued, 0) - ISNULL((
472	   472	                              SELECT SUM(ARD.Qty)
473	   473	                              FROM   dbo.HR_AssetReturnDetail ARD
474	   474	                              INNER  JOIN dbo.HR_AssetReturn AR ON AR.ID = ARD.ReturnID
475	   475	                              WHERE  ARD.IssueDetailID = AID.ID
476	   476	                                AND  AR.Status = 1), 0) AS Balance) Bal
477	   477	            WHERE  F.FNFSettlementID = @CaseID
478	   478	              AND  Bal.Balance > 0
479	   479	              AND  NOT EXISTS (SELECT 1 FROM dbo.HR_FNFRecovery R
480	   480	                               WHERE R.FNFSettlementID = @CaseID
481	   481	                                 AND R.AssetIssueDetailID = AID.ID);", conn, tx))
482	   482	        {
483	   483	            cmd.Parameters.AddWithValue("@CaseID", caseId);
484	   484	            cmd.Parameters.AddWithValue("@UserID", userId);
485	   485	            cmd.Parameters.AddWithValue("@SystemName", Trunc(systemName, 50));
486	   486	            added += cmd.ExecuteNonQuery();
487	   487	        }
488	   488	
489	   489	        return added;
490	   490	    }
491	   491	
492	   492	    /// <summary>Confirmed recoveries only - a Waived row is kept for the audit trail
493	   493	    /// but must never reach the deductions.</summary>
494	   494	    public static decimal ConfirmedRecoveryTotal(SqlConnection conn, SqlTransaction tx, long caseId)
495	   495	    {
496	   496	        using (var cmd = new SqlCommand(@"
497	   497	            SELECT ISNULL(SUM(Amount), 0)
498	   498	            FROM   dbo.HR_FNFRecovery
499	   499	            WHERE  FNFSettlementID = @CaseID
500	   500	              AND  Status = 1
501	   501	              AND  RecoveryStatus = 'Confirmed'", conn, tx))
502	   502	        {
503	   503	            cmd.Parameters.AddWithValue("@CaseID", caseId);
504	   504	            return Convert.ToDecimal(cmd.ExecuteScalar());
505	   505	        }
506	   506	    }
507	   507	
508	   508	    // -------------------------------------------------------------------------
509	   509	    //  Clearance verdict (stage 4)
510	   510	    // -------------------------------------------------------------------------
511	   511	
512	   512	    /// <summary>
513	   513	    /// Recomputes IsClearanceReady and the block reason on the header, cached there so
514	   514	    /// the LIST grid can show the verdict without re-reading nine checklist rows for
515	   515	    /// every case on the page.
516	   516	    ///
517	   517	    /// The reason names the FIRST outstanding requirement in checklist order, which is
518	   518	    /// what makes the message actionable ("Finance clearance pending.") instead of a
519	   519	    /// count of failures.
520	   520	    /// </summary>
521	   521	    public static bool EvaluateClearance(SqlConnection conn, SqlTransaction tx, long caseId)
522	   522	    {
523	   523	        string blockReason = null;
524	   524	        int outstanding;
525	   525	
526	   526	        using (var cmd = new SqlCommand(@"
527	   527	            SELECT TOP 1 CheckName
528	   528	            FROM   dbo.HR_FNFCheck
529	   529	            WHERE  FNFSettlementID = @CaseID
530	   530	              AND  CheckKind = @Kind
531	   531	              AND  IsRequired = 1
532	   532	              AND  ISNULL(Result, '') <> 'Yes'
533	   533	            ORDER  BY SortOrder, FNFCheckID", conn, tx))
534	   534	        {
535	   535	            cmd.Parameters.AddWithValue("@CaseID", caseId);
536	   536	            cmd.Parameters.AddWithValue("@Kind", KindReadiness);
537	   537	            object first = cmd.ExecuteScalar();
538	   538	            if (first != null && first != DBNull.Value)
539	   539	                blockReason = Convert.ToString(first) + " is pending.";
540	   540	        }
541	   541	
542	   542	        using (var cmd = new SqlCommand(@"
543	   543	            SELECT COUNT(*)
544	   544	            FROM   dbo.HR_FNFCheck
545	   545	            WHERE  FNFSettlementID = @CaseID
546	   546	              AND  CheckKind = @Kind
547	   547	              AND  IsRequired = 1
548	   548	              AND  ISNULL(Result, '') <> 'Yes'", conn, tx))
549	   549	        {
550	   550	            cmd.Parameters.AddWithValue("@CaseID", caseId);
551	   551	            cmd.Parameters.AddWithValue("@Kind", KindReadiness);
552	   552	            outstanding = Convert.ToInt32(cmd.ExecuteScalar());
553	   553	        }
554	   554	
555	   555	        if (outstanding > 1)
556	   556	            blockReason = blockReason + " (" + outstanding + " requirements outstanding)";
557	   557	
558	   558	        bool ready = (outstanding == 0);
559	   559	
560	   560	        using (var cmd = new SqlCommand(@"
561	   561	            UPDATE dbo.HR_FNFSettlement
562	   562	            SET    IsClearanceReady     = @Ready,
563	   563	                   ClearanceBlockReason = @Reason
564	   564	            WHERE  FNFSettlementID = @CaseID", conn, tx))
565	   565	        {
566	   566	            cmd.Parameters.AddWithValue("@CaseID", caseId);
567	   567	            cmd.Parameters.AddWithValue("@Ready", ready);
568	   568	            cmd.Parameters.AddWithValue("@Reason", (object)blockReason ?? DBNull.Value);
569	   569	            cmd.ExecuteNonQuery();
570	   570	        }
571	   571	
572	   572	        return ready;
573	   573	    }
574	   574	
575	   575	    // -------------------------------------------------------------------------
576	   576	    //  Workflow rules - the single source of "who may still change what"
577	   577	    // -------------------------------------------------------------------------
578	   578	
579	   579	    /// <summary>A case is editable only while it is a draft. Once submitted it opens
580	   580	    /// read-only rather than disappearing, because "what did we actually agree?" is
581	   581	    /// the commonest question these screens get.</summary>
582	   582	    public static bool CanEdit(string workflowStatus)
583	   583	    {
584	   584	        return string.Equals(workflowStatus, StatusDraft, StringComparison.OrdinalIgnoreCase)
585	   585	            || string.IsNullOrEmpty(workflowStatus);
586	   586	    }
587	   587	
588	   588	    public static bool CanSubmit(string workflowStatus, bool clearanceReady)
589	   589	    {
590	   590	        return CanEdit(workflowStatus) && clearanceReady;
591	   591	    }
592	   592	
593	   593	    public static string OpenButtonText(bool editable)
594	   594	    {
595	   595	        return editable ? "Open" : "View";
596	   596	    }
597	   597	
598	   598	    /// <summary>CSS class for the status pill. Matches the vocabulary the loan screens
599	   599	    /// already use, so one stylesheet serves both.</summary>
600	   600	    public static string StatusPill(string workflowStatus)
601	   601	    {
602	   602	        switch ((workflowStatus ?? string.Empty).Trim().ToLowerInvariant())
603	   603	        {
604	   604	            case "draft":     return "Pending";
605	   605	            case "submitted": return "Pending";
606	   606	            case "approved":  return "Approved";
607	   607	            case "paid":      return "Approved";
608	   608	            case "cancelled": return "Cancelled";
609	   609	            default:          return "Cancelled";
610	   610	        }
611	   611	    }
612	   612	
613	   613	    // -------------------------------------------------------------------------
614	   614	
615	   615	    /// <summary>
616	   616	    /// SystemName column widths are inconsistent across this schema (20 to 128), and
617	   617	    /// an over-long machine name makes every save fail with "String or binary data
618	   618	    /// would be truncated" - which on 2014 does not name the column.
619	   619	    /// </summary>
620	   620	    private static string Trunc(string value, int max)
621	   621	    {
622	   622	        if (string.IsNullOrEmpty(value)) return string.Empty;
623	   623	        return value.Length <= max ? value : value.Substring(0, max);
624	   624	    }
625	   625	}
