1156 /// <summary>
1157 /// The per-month amount override the payroll proc reads. Upsert, so recalculating and
1158 /// re-approving replaces the figure rather than doubling it.
1159 /// </summary>
1160 private static void UpsertAdditionalHead(SqlConnection conn, SqlTransaction tx, long employeeId,
1161 long headId, decimal amount, int month, int year,
1162 long categoryId, long branchId, string component,
1163 int userId, string systemName)
1164 {
1165 using (var cmd = new SqlCommand(@"
1166 UPDATE dbo.HR_SalaryAdditionalHead
1167 SET Amount = @Amount, Remarks = @Remarks,
1168 EditUserMasterID = @UserID, EditUserDateTime = GETDATE()
1169 WHERE EmployeeMasterID = @Emp AND SalaryHeadMasterID = @Head
1170 AND AttendMonth = @M AND AttendYear = @Y
1171 AND CategoryMasterID = @Cat AND BranchMasterID = @Br;
1172
1173 IF @@ROWCOUNT = 0
1174 INSERT INTO dbo.HR_SalaryAdditionalHead
1175 (SalaryHeadMasterID, AccountHeadCode, EmployeeMasterID, Amount, Remarks,
1176 AttendMonth, AttendYear, CategoryMasterID, BranchMasterID,
1177 EntryUserMasterID, EntryUserDateTime, SystemName)
1178 SELECT @Head, ISNULL(SH.Code, ''), @Emp, @Amount, @Remarks,
1179 @M, @Y, @Cat, @Br, @UserID, GETDATE(), @SystemName
1180 FROM dbo.HR_SalaryHeadMaster SH
1181 WHERE SH.SalaryHeadMasterID = @Head;", conn, tx))
1182 {
1183 cmd.Parameters.AddWithValue("@Amount", amount);
1184 cmd.Parameters.AddWithValue("@Remarks", "F&F settlement - " + component);
1185 cmd.Parameters.AddWithValue("@Emp", employeeId);
1186 cmd.Parameters.AddWithValue("@Head", headId);
1187 cmd.Parameters.AddWithValue("@M", month);
1188 cmd.Parameters.AddWithValue("@Y", year);
1189 cmd.Parameters.AddWithValue("@Cat", categoryId);
1190 cmd.Parameters.AddWithValue("@Br", branchId);
1191 cmd.Parameters.AddWithValue("@UserID", userId);
1192 cmd.Parameters.AddWithValue("@SystemName", Trunc(systemName, 50));
1193 cmd.ExecuteNonQuery();
1194 }
1195 }
