1197 /// <summary>
1198 /// Settles the loan schedule this settlement recovered.
1199 ///
1200 /// Every unpaid installment is marked paid, not just the settlement month's, because
1201 /// the settlement recovered the WHOLE outstanding. Leaving them unpaid would inflate
1202 /// the loan's outstanding for ever, since outstanding is derived as SUM(EMIAmount)
1203 /// over unpaid rows.
1204 /// </summary>
1205 public static int SettleLoanSchedule(SqlConnection conn, SqlTransaction tx, long caseId)
1206 {
1207 using (var cmd = new SqlCommand(@"
1208 UPDATE S
1209 SET S.IsPaid = 1
1210 FROM dbo.HR_LoanEMISchedule S
1211 INNER JOIN dbo.HR_FNFSettlement F ON F.EmployeeMasterID = S.EmployeeMasterID
1212 WHERE F.FNFSettlementID = @Id
1213 AND S.IsPaid = 0
1214 AND S.Status = 1
1215 AND EXISTS (SELECT 1 FROM dbo.HR_FNFSettlementDetail D
1216 WHERE D.FNFSettlementID = @Id
1217 AND D.ComponentType = @Comp
1218 AND D.Amount > 0)", conn, tx))
1219 {
1220 cmd.Parameters.AddWithValue("@Id", caseId);
1221 cmd.Parameters.AddWithValue("@Comp", CompLoanRecovery);
1222 return cmd.ExecuteNonQuery();
1223 }
1224 }
