1226 /// <summary>
1227 /// True when the F&amp;F tables exist in THIS database.
1228 ///
1229 /// Tenant databases drift: migrations 110-113 may not have reached a client yet, and
1230 /// SQL referencing a missing table fails at parse time, so no <c>IF</c> inside the batch
1231 /// can save it. Payroll must keep running on a database that has never seen F&amp;F, so
1232 /// any payroll-side F&amp;F predicate has to be appended conditionally.
1233 ///
1234 /// Deliberately NOT cached in a static: the menu-schema probe does that and it is a
1235 /// documented trap — after the migration applies, the app pool has to be recycled before
1236 /// the cached answer changes. One cheap lookup per payroll Go is worth more than that.
1237 /// </summary>
1238 public static bool SchemaReady(SqlConnection conn, SqlTransaction tx)
1239 {
1240 using (var cmd = new SqlCommand(@"
1241 SELECT CASE WHEN OBJECT_ID('dbo.HR_FNFSettlement', 'U') IS NOT NULL
1242 AND OBJECT_ID('dbo.HR_FNFSettlementDetail', 'U') IS NOT NULL
1243 AND OBJECT_ID('dbo.HR_FNFConfig', 'U') IS NOT NULL
1244 THEN 1 ELSE 0 END", conn, tx))
1245 {
1246 return Convert.ToInt32(cmd.ExecuteScalar()) == 1;
1247 }
1248 }
1249
1250 /// <summary>
1251 /// A predicate for SalaryGenerate's loan-EMI query that removes any employee whose whole
1252 /// loan has already been recovered by an approved settlement. Without it the settlement
1253 /// month deducts the installment TWICE — once by <c>InjectLoanEMIRows</c>, once by the
1254 /// settlement's own LoanRecovery line.
1255 ///
1256 /// Returns an empty string when the F&amp;F tables are absent, so the caller can splice it
1257 /// in unconditionally.
1258 /// </summary>
1259 public static string LoanSuppressionPredicate(SqlConnection conn, string scheduleAlias)
1260 {
1261 if (!SchemaReady(conn, null)) return string.Empty;
1262
1263 string a = string.IsNullOrEmpty(scheduleAlias) ? "les" : scheduleAlias;
1264
1265 return @"
1266 AND NOT EXISTS (
1267 SELECT 1
1268 FROM dbo.HR_FNFSettlement F
1269 INNER JOIN dbo.HR_FNFSettlementDetail D ON D.FNFSettlementID = F.FNFSettlementID
1270 INNER JOIN dbo.HR_FNFConfig C ON C.CompanyMasterID = F.CompanyMasterID
1271 WHERE F.EmployeeMasterID = " + a + @".EmployeeMasterID
1272 AND F.CompanyMasterID = " + a + @".CompanyMasterID
1273 AND F.Status = 1
1274 AND F.WorkflowStatus IN ('Approved', 'Paid')
1275 AND D.ComponentType = 'LoanRecovery'
1276 AND D.Amount > 0
1277 AND C.SuppressLoanEMIOnSettlement = 1) ";
1278 }
1279
1280 /// <summary>
1281 /// True when this employee has an approved settlement that already recovered their whole
1282 /// loan — in which case the monthly EMI injection must be suppressed, or the settlement
1283 /// month deducts the installment twice: once by payroll, once by the settlement.
1284 /// </summary>
1285 public static bool HasSettledLoan(SqlConnection conn, SqlTransaction tx, long employeeId, long companyId)
1286 {
1287 using (var cmd = new SqlCommand(@"
1288 SELECT COUNT(*)
1289 FROM dbo.HR_FNFSettlement F
1290 INNER JOIN dbo.HR_FNFSettlementDetail D ON D.FNFSettlementID = F.FNFSettlementID
1291 INNER JOIN dbo.HR_FNFConfig C ON C.CompanyMasterID = F.CompanyMasterID
1292 WHERE F.EmployeeMasterID = @Emp
1293 AND F.CompanyMasterID = @Company
1294 AND F.Status = 1
1295 AND F.WorkflowStatus IN ('Approved', 'Paid')
1296 AND D.ComponentType = @Comp
1297 AND D.Amount > 0
1298 AND C.SuppressLoanEMIOnSettlement = 1", conn, tx))
1299 {
1300 cmd.Parameters.AddWithValue("@Emp", employeeId);
1301 cmd.Parameters.AddWithValue("@Company", companyId);
1302 cmd.Parameters.AddWithValue("@Comp", CompLoanRecovery);
1303 return Convert.ToInt32(cmd.ExecuteScalar()) > 0;
1304 }
1305 }
