1316 private static bool Bool(DataRow r, string col)
1317 {
1318 return r.Table.Columns.Contains(col) && r[col] != DBNull.Value && Convert.ToBoolean(r[col]);
1319 }
1320
1321 private static decimal Dec(DataRow r, string col, decimal fallback)
1322 {
1323 if (!r.Table.Columns.Contains(col) || r[col] == DBNull.Value) return fallback;
1324 return Convert.ToDecimal(r[col]);
1325 }
