277	        cmbEmployee.Value = null;
278	        cmbEmployee.Enabled = true;
279	
280	        dtPlannedCalc.Value = null;
281	        dtPlannedSettle.Value = null;
282	        dtActualCalc.Value = null;
283	        spnTat.Value = null;
284	        cmbHrExec.Value = null;
285	        cmbPayrollExec.Value = null;
286	        cmbFinanceExec.Value = null;
287	        cmbApprover.Value = null;
288	        memRemarks.Text = string.Empty;
289	
290	        litBanner.Text = string.Empty;
291	        litSettleNotes.Text = string.Empty;
292	        litTotals.Text = string.Empty;
293	
294	        int eligible = LoadEligibleEmployees();
295	
296	        if (eligible == 0)
297	        {
298	            // Say WHY the list is empty and where to fix it. The eligibility rule is
299	            // deliberately strict - a settlement is for someone who is actually leaving -
300	            // so an empty list is usually correct and the user needs to know that.
301	            litSnapshot.Text =
