91	    91	    /// that state. An empty dropdown under a "pick the employee" instruction, with no
92	    92	    /// reason given, is indistinguishable from a broken screen - so the caller uses the
93	    93	    /// count to explain itself.
94	    94	    /// </summary>
95	    95	    private int LoadEligibleEmployees()
