156	   156	    protected void CaseGridView_BeforePerformDataSelect(object sender, EventArgs e)
157	   157	    {
158	   158	        // Supplied here rather than only on the first request: paging, sorting, the page-size
159	   159	        // picker and the filter row all raise the GRID's own callback, which passes through
160	   160	        // neither Page_Load's !IsPostBack branch nor the panel handler - so a grid bound only
161	   161	        // once comes back with no rows and no pager.
162	   162	        CaseGridView.DataSource = LoadCases();
163	   163	    }
164	   164	
165	   165	    private DataTable LoadCases()
166	   166	    {
167	   167	        // An Admin / HR Admin sees every case in the company; anyone else sees only the
168	   168	        // cases they are named on. Scoped in the single query the grid runs, so the drill
169	   169	        // and the toolbar cannot widen it.
170	   170	        string scope = RoleHelper.IsAdmin(Session["UserRole"])
171	   171	            ? string.Empty
172	   172	            : @" AND (F.HRExecutiveUserMasterID = @UserID
173	   173	                   OR F.PayrollExecutiveUserMasterID = @UserID
174	   174	                   OR F.FinanceExecutiveUserMasterID = @UserID
175	   175	                   OR F.ApproverUserMasterID = @UserID
176	   176	                   OR F.EntryUserMasterID = @UserID) ";
177	   177	
178	   178	        string sql = @"
179	   179	            SELECT F.FNFSettlementID, F.CaseNo, F.CaseDate,
180	   180	                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FatherName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.LastName)),''), '')) AS EmployeeName,
181	   181	                   ISNULL(EM.Code, '')      AS EmployeeCode,
182	   182	                   F.LastWorkingDate, F.CasePriority, F.WorkflowStatus,
183	   183	                   CASE WHEN ISNULL(F.IsClearanceReady, 0) = 1 THEN 'Ready'
184	   184	                        ELSE ISNULL(F.ClearanceBlockReason, 'Not checked') END AS ClearanceText
185	   185	            FROM   dbo.HR_FNFSettlement F
186	   186	            LEFT   JOIN dbo.HR_EmployeeMaster EM ON EM.EmployeeMasterID = F.EmployeeMasterID
187	   187	            WHERE  F.Status = 1
188	   188	              AND  F.CompanyMasterID = @CompanyID " + scope + @"
189	   189	            ORDER  BY F.FNFSettlementID DESC";
190	   190	
191	   191	        var table = new DataTable();
192	   192	        try
193	   193	        {
194	   194	            using (SqlConnection conn = CreateConnection())
195	   195	            using (var cmd = new SqlCommand(sql, conn))
196	   196	            {
197	   197	                cmd.Parameters.AddWithValue("@CompanyID", CompanyId);
198	   198	                cmd.Parameters.AddWithValue("@UserID", UserId);
199	   199	                using (var da = new SqlDataAdapter(cmd)) da.Fill(table);
200	   200	            }
201	   201	        }
202	   202	        catch (Exception ex)
203	   203	        {
204	   204	            ErrorLogHelper.Log(ex, "FNFSettlement.LoadCases");
205	   205	        }
206	   206	        return table;
207	   207	    }
