328	   328	    private void HandleCreate()
329	   329	    {
330	   330	        if (cmbEmployee.Value == null)
331	   331	        {
332	   332	            FnfPanel.JSProperties["cpMsg"] = "Pick the employee to settle first.";
333	   333	            return;
334	   334	        }
335	   335	
336	   336	        long employeeId = Convert.ToInt64(cmbEmployee.Value);
337	   337	        int windowDays = ComplianceWindowDaysForCompany();
338	   338	        long newId;
339	   339	
340	   340	        using (SqlConnection conn = CreateConnection())
341	   341	        {
342	   342	            conn.Open();
343	   343	            // One transaction for the whole thing: the header, the nine checklist rows, the
344	   344	            // auto-answers, the discovered recoveries and the clearance verdict. A case must
345	   345	            // never exist with a half-built checklist.
346	   346	            using (SqlTransaction tx = conn.BeginTransaction())
347	   347	            {
348	   348	                try
349	   349	                {
350	   350	                    newId = FNFCaseService.CreateCase(conn, tx, employeeId, CompanyId,
351	   351	                                                      UserId, HostNameCapped(), windowDays);
352	   352	                    tx.Commit();
353	   353	                }
354	   354	                catch
355	   355	                {
356	   356	                    try { tx.Rollback(); } catch { /* connection already gone */ }
357	   357	                    throw;
358	   358	                }
359	   359	            }
360	   360	        }
361	   361	
362	   362	        LoadCase(newId);
363	   363	        FnfPanel.JSProperties["cpMsg"] = "F&F case " + txtCaseNo.Text + " created.";
364	   364	    }
