381	   381	    private void LoadCase(long id)
382	   382	    {
383	   383	        const string sql = @"
384	   384	            SELECT F.*,
385	   385	                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FatherName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.LastName)),''), '')) AS EmployeeName,
386	   386	                   ISNULL(EM.Code, '')          AS EmployeeCode,
387	   387	                   -- These two tables name their caption columns DepartmentName /
388	   388	                   -- DesignationName, not Name. Getting that wrong made both Create and
389	   389	                   -- Open throw Invalid column name Name, so the case was created but its
390	   390	                   -- snapshot never loaded and the form sat on its placeholder text.
391	   391	                   ISNULL(D.DepartmentName, '')  AS DepartmentName,
392	   392	                   ISNULL(G.DesignationName, '') AS DesignationName,
393	   393	                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(MG.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(MG.LastName)),''), '')) AS ManagerName,
394	   394	                   EBS.BasicAmount, EBS.GrossAmount, EBS.CTCAmount
395	   395	            FROM   dbo.HR_FNFSettlement F
396	   396	            LEFT   JOIN dbo.HR_EmployeeMaster   EM ON EM.EmployeeMasterID   = F.EmployeeMasterID
397	   397	            LEFT   JOIN dbo.HR_DepartmentMaster D  ON D.DepartmentMasterID  = F.DepartmentMasterID
398	   398	            LEFT   JOIN dbo.HR_DesignationMaster G ON G.DesignationMasterID = F.DesignationMasterID
399	   399	            LEFT   JOIN dbo.HR_EmployeeMaster   MG ON MG.EmployeeMasterID   = F.ReportingPersonID
400	   400	            OUTER  APPLY (SELECT TOP 1 B.BasicAmount, B.GrossAmount, B.CTCAmount
401	   401	                          FROM   dbo.HR_EmployeeBasicSalary B
402	   402	                          WHERE  B.EmployeeMasterID = F.EmployeeMasterID
403	   403	                          ORDER  BY B.FromDate DESC) EBS
404	   404	            WHERE  F.FNFSettlementID = @Id";
405	   405	
406	   406	        DataRow row = null;
407	   407	        using (SqlConnection conn = CreateConnection())
408	   408	        using (var cmd = new SqlCommand(sql, conn))
409	   409	        {
410	   410	            cmd.Parameters.AddWithValue("@Id", id);
411	   411	            var dt = new DataTable();
412	   412	            using (var da = new SqlDataAdapter(cmd)) da.Fill(dt);
413	   413	            if (dt.Rows.Count > 0) row = dt.Rows[0];
414	   414	        }
415	   415	
416	   416	        if (row == null)
417	   417	        {
418	   418	            FnfPanel.JSProperties["cpMsg"] = "That F&F case no longer exists.";
419	   419	            FnfPanel.JSProperties["cpReloadList"] = true;
420	   420	            return;
421	   421	        }
422	   422	
423	   423	        CurrentCaseId = id;
424	   424	        CurrentStatus = Convert.ToString(row["WorkflowStatus"]);
425	   425	
426	   426	        txtCaseNo.Text = Convert.ToString(row["CaseNo"]);
427	   427	        txtStatus.Text = CurrentStatus;
428	   428	        dtCaseDate.Value = row["CaseDate"];
429	   429	        cmbPriority.Value = Convert.ToString(row["CasePriority"]);
430	   430	
431	   431	        // The employee cannot be changed once the case exists - the whole snapshot was
432	   432	        // taken from them. Shown for reference, locked against editing.
433	   433	        cmbEmployee.Value = Convert.ToInt64(row["EmployeeMasterID"]);
434	   434	        cmbEmployee.Enabled = false;
435	   435	
436	   436	        dtPlannedCalc.Value   = NullIfDbNull(row["PlannedCalcStartDate"]);
437	   437	        dtPlannedSettle.Value = NullIfDbNull(row["PlannedSettlementDate"]);
438	   438	        dtActualCalc.Value    = NullIfDbNull(row["ActualCalcStartDate"]);
439	   439	        spnTat.Value          = NullIfDbNull(row["ApprovalTurnaroundDays"]);
440	   440	        cmbHrExec.Value       = NullIfDbNull(row["HRExecutiveUserMasterID"]);
441	   441	        cmbPayrollExec.Value  = NullIfDbNull(row["PayrollExecutiveUserMasterID"]);
442	   442	        cmbFinanceExec.Value  = NullIfDbNull(row["FinanceExecutiveUserMasterID"]);
443	   443	        cmbApprover.Value     = NullIfDbNull(row["ApproverUserMasterID"]);
444	   444	        memRemarks.Text       = Convert.ToString(row["Remarks"]);
445	   445	
446	   446	        litSnapshot.Text = BuildSnapshotHtml(row);
447	   447	        litBanner.Text = BuildBannerHtml(row);
448	   448	
449	   449	        ReadinessGrid.DataBind();
450	   450	        RecoveryGrid.DataBind();
451	   451	        SettleGrid.DataBind();
452	   452	        VerifyGrid.DataBind();
453	   453	        HandoverGrid.DataBind();
454	   454	        RenderTotals();
455	   455	        RenderSettlementNotes(row);
456	   456	
457	   457	        bool editable = FNFCaseService.CanEdit(CurrentStatus);
458	   458	        FnfPanel.JSProperties["cpCreating"] = "0";
459	   459	        FnfPanel.JSProperties["cpLocked"] = editable ? "0" : "1";
460	   460	    }
