489	   489	    private string BuildSnapshotHtml(DataRow row)
490	   490	    {
491	   491	        var sb = new System.Text.StringBuilder();
492	   492	        sb.Append("<table class=\"fnf-kv\" style=\"border-collapse:collapse\"><tr>");
493	   493	        sb.Append(Cell("Employee", row["EmployeeName"]));
494	   494	        sb.Append(Cell("Code", row["EmployeeCode"]));
495	   495	        sb.Append(Cell("Department", row["DepartmentName"]));
496	   496	        sb.Append(Cell("Designation", row["DesignationName"]));
497	   497	        sb.Append(Cell("Manager", row["ManagerName"]));
498	   498	        sb.Append("</tr><tr>");
499	   499	        sb.Append(DateCell("Joining Date", row["DateOfJoining"]));
500	   500	        sb.Append(DateCell("Resignation Date", row["ResignDate"]));
501	   501	        sb.Append(DateCell("Last Working Day", row["LastWorkingDate"]));
502	   502	        sb.Append(Cell("Notice Required (days)", row["NoticeDaysRequired"]));
503	   503	        sb.Append(Cell("Notice Served (days)", NoticeServedDays(row)));
504	   504	        sb.Append("</tr><tr>");
505	   505	        sb.Append(MoneyCell("Basic", row["BasicAmount"]));
506	   506	        sb.Append(MoneyCell("Gross", row["GrossAmount"]));
507	   507	        sb.Append(MoneyCell("CTC", row["CTCAmount"]));
508	   508	        sb.Append(DateCell("Compliance Window Ends", row["ComplianceWindowEnd"]));
509	   509	        sb.Append("</tr></table>");
510	   510	        return sb.ToString();
