512	   512	
513	   513	    /// <summary>
514	   514	    /// Days actually served between resignation and the last working day. Derived rather
515	   515	    /// than stored: both dates are on the case, so a stored copy could only ever disagree
516	   516	    /// with them.
517	   517	    /// </summary>
518	   518	    private static object NoticeServedDays(DataRow row)
519	   519	    {
520	   520	        if (row["ResignDate"] == DBNull.Value || row["LastWorkingDate"] == DBNull.Value)
521	   521	            return null;
522	   522	
523	   523	        DateTime from = Convert.ToDateTime(row["ResignDate"]);
524	   524	        DateTime to = Convert.ToDateTime(row["LastWorkingDate"]);
525	   525	        int days = (int)(to.Date - from.Date).TotalDays;
526	   526	        return days < 0 ? 0 : days;
527	   527	    }
528	   528	
529	   529	    private string BuildBannerHtml(DataRow row)
530	   530	    {
531	   531	        bool editable = FNFCaseService.CanEdit(Convert.ToString(row["WorkflowStatus"]));
532	   532	        if (!editable)
533	   533	        {
534	   534	            return "<div class=\"fnf-banner locked\">This case is " +
535	   535	                   HttpUtility.HtmlEncode(Convert.ToString(row["WorkflowStatus"])) +
536	   536	                   " and is shown read-only.</div>";
537	   537	        }
538	   538	
539	   539	        bool ready = row["IsClearanceReady"] != DBNull.Value && Convert.ToBoolean(row["IsClearanceReady"]);
540	   540	        if (ready)
541	   541	        {
542	   542	            return "<div class=\"fnf-banner ready\">Clearance Ready &mdash; the settlement can be " +
543	   543	                   "calculated for this case.</div>";
544	   544	        }
545	   545	
546	   546	        string reason = Convert.ToString(row["ClearanceBlockReason"]);
