677	   677	        if (CurrentCaseId <= 0) return;
678	   678	
679	   679	        int found;
680	   680	        using (SqlConnection conn = CreateConnection())
681	   681	        {
682	   682	            conn.Open();
683	   683	            using (SqlTransaction tx = conn.BeginTransaction())
684	   684	            {
685	   685	                try
686	   686	                {
687	   687	                    FNFCaseService.SeedReadiness(conn, tx, CurrentCaseId);
688	   688	                    FNFCaseService.AutoAnswerReadiness(conn, tx, CurrentCaseId);
689	   689	                    found = FNFCaseService.DiscoverRecoveries(conn, tx, CurrentCaseId, UserId, HostNameCapped());
690	   690	                    FNFCaseService.EvaluateClearance(conn, tx, CurrentCaseId);
691	   691	                    tx.Commit();
692	   692	                }
693	   693	                catch
694	   694	                {
695	   695	                    try { tx.Rollback(); } catch { /* connection already gone */ }
696	   696	                    throw;
697	   697	                }
698	   698	            }
699	   699	        }
700	   700	
701	   701	        LoadCase(CurrentCaseId);
702	   702	        FnfPanel.JSProperties["cpMsg"] = found > 0
703	   703	            ? "Readiness re-checked. " + found + " new recovery row(s) found."
704	   704	            : "Readiness re-checked. No new recoveries.";
