1101 /// <summary>
1102 /// Re-totals the header from the detail rows after a manual line changes, WITHOUT
1103 /// re-running the component calculation - the user has only changed one typed figure,
1104 /// and recalculating would also re-read leave, loans and assets underneath them.
1105 /// </summary>
1106 private void RecalculateTotalsOnly()
1107 {
1108 const string sql = @"
1109 UPDATE F
1110 SET F.TotalEarnings = T.Earnings,
1111 F.TotalDeductions = T.Deductions,
1112 F.NetPayable = T.Earnings - T.Deductions
1113 FROM dbo.HR_FNFSettlement F
1114 CROSS APPLY (SELECT
1115 ISNULL(SUM(CASE WHEN D.[Add/Deduct] = 'Add' THEN D.Amount ELSE 0 END), 0) AS Earnings,
1116 ISNULL(SUM(CASE WHEN D.[Add/Deduct] = 'Deduct' THEN D.Amount ELSE 0 END), 0) AS Deductions
1117 FROM dbo.HR_FNFSettlementDetail D
1118 WHERE D.FNFSettlementID = F.FNFSettlementID) T
1119 WHERE F.FNFSettlementID = @Id";
1120
1121 using (SqlConnection conn = CreateConnection())
1122 using (var cmd = new SqlCommand(sql, conn))
1123 {
1124 cmd.Parameters.AddWithValue("@Id", CurrentCaseId);
1125 conn.Open();
1126 cmd.ExecuteNonQuery();
1127 }
1128
1129 RenderTotals();
1130 }
1131
1132 private void RenderTotals()
1133 {
1134 const string sql = @"
1135 SELECT ISNULL(TotalEarnings,0), ISNULL(TotalDeductions,0), ISNULL(NetPayable,0),
1136 ISNULL(PerDayRate,0), ISNULL(PerDayRateBasis,'')
1137 FROM dbo.HR_FNFSettlement WHERE FNFSettlementID = @Id";
1138
1139 using (SqlConnection conn = CreateConnection())
1140 using (var cmd = new SqlCommand(sql, conn))
1141 {
1142 cmd.Parameters.AddWithValue("@Id", CurrentCaseId);
1143 conn.Open();
1144 using (SqlDataReader rd = cmd.ExecuteReader())
1145 {
1146 if (!rd.Read()) { litTotals.Text = string.Empty; return; }
1147
1148 decimal earnings = rd.GetDecimal(0);
1149 decimal deductions = rd.GetDecimal(1);
1150 decimal net = rd.GetDecimal(2);
1151 decimal rate = rd.GetDecimal(3);
1152 string basis = rd.GetString(4);
1153
1154 string netClass = net < 0 ? "blocked" : "ready";
1155 string netLabel = net < 0 ? "Recoverable from employee" : "Net Payable";
1156
1157 litTotals.Text =
1158 "<table class=\"fnf-kv\" style=\"border-collapse:collapse;margin-top:10px\"><tr>"
1159 + Cell("Total Earnings", earnings.ToString("n2"))
1160 + Cell("Total Deductions", deductions.ToString("n2"))
1161 + Cell(netLabel, Math.Abs(net).ToString("n2"))
1162 + Cell("Per-day Rate", rate.ToString("n2") + (basis.Length > 0 ? " (" + basis + ")" : ""))
1163 + "</tr></table>"
1164 + "<div class=\"fnf-banner " + netClass + "\" style=\"margin-top:10px\">"
1165 + HttpUtility.HtmlEncode(netLabel) + ": " + Math.Abs(net).ToString("n2") + "</div>";
1166 }
1167 }
1168 }
