845 /// <summary>
846 /// Why the verification checklist is not complete, or null when it is.
847 ///
848 /// AN EMPTY CHECKLIST IS NOT A PASSED CHECKLIST. This used to ask only "is any required
849 /// row failing", which returns nothing when there are no rows at all - so a case whose
850 /// checklist had never been seeded sailed through Submit as if fully verified. That is
851 /// exactly how FNF-2026-00002 reached Approved: its two settlement lines were typed by
852 /// hand on the Settlement tab, Calculate was never run, so no verification rows existed
853 /// and nothing objected.
854 ///
855 /// The rows are seeded by Calculate, so requiring them to exist also guarantees the
856 /// figures being signed off were actually computed rather than typed.
857 /// </summary>
858 private string VerificationIncompleteReason(SqlConnection conn)
859 {
860 using (var cmd = new SqlCommand(@"
861 SELECT COUNT(*) FROM dbo.HR_FNFCheck
862 WHERE FNFSettlementID = @Id AND CheckKind = @Kind", conn))
863 {
864 cmd.Parameters.AddWithValue("@Id", CurrentCaseId);
865 cmd.Parameters.AddWithValue("@Kind", FNFCaseService.KindVerification);
866
867 if (Convert.ToInt32(cmd.ExecuteScalar()) == 0)
868 return "the checklist has not been created yet - press Calculate first, "
869 + "which works out the figures and seeds the checks.";
870 }
871
872 using (var cmd = new SqlCommand(@"
873 SELECT TOP 1 CheckName + ' is ' + ISNULL(Result, 'not checked') + '.'
874 FROM dbo.HR_FNFCheck
875 WHERE FNFSettlementID = @Id AND CheckKind = @Kind
876 AND IsRequired = 1 AND ISNULL(Result, '') NOT IN ('Pass', 'NA')
877 ORDER BY SortOrder, FNFCheckID", conn))
878 {
879 cmd.Parameters.AddWithValue("@Id", CurrentCaseId);
880 cmd.Parameters.AddWithValue("@Kind", FNFCaseService.KindVerification);
881 object value = cmd.ExecuteScalar();
882 return (value == null || value == DBNull.Value) ? null : Convert.ToString(value);
883 }
884 }
