1474 protected void RecoveryGrid_RowDeleting(object sender, DevExpress.Web.Data.ASPxDataDeletingEventArgs e)
1475 {
1476 e.Cancel = true;
1477 try
1478 {
1479 if (!GuardRecoveryEdit()) return;
1480
1481 // Soft delete, the house convention. A hard delete would also let the auto-scan
1482 // put the row straight back on the next Re-check.
1483 const string sql = @"
1484 UPDATE dbo.HR_FNFRecovery
1485 SET Status = 0, EditUserMasterID = @UserID, EditUserDateTime = GETDATE()
1486 WHERE FNFRecoveryID = @Id AND FNFSettlementID = @CaseID";
1487
1488 using (SqlConnection conn = CreateConnection())
1489 using (var cmd = new SqlCommand(sql, conn))
1490 {
1491 cmd.Parameters.AddWithValue("@UserID", UserId);
1492 cmd.Parameters.AddWithValue("@Id", Convert.ToInt64(e.Keys[RecoveryGrid.KeyFieldName]));
1493 cmd.Parameters.AddWithValue("@CaseID", CurrentCaseId);
1494 conn.Open();
1495 cmd.ExecuteNonQuery();
1496 }
1497
1498 RecoveryGrid.CancelEdit();
1499 }
1500 catch (Exception ex)
1501 {
1502 ErrorLogHelper.Log(ex, "FNFSettlement.RecoveryDelete");
1503 FnfPanel.JSProperties["cpMsg"] = ErrorLogHelper.FriendlyMessage;
1504 }
1505 }
