1507 private bool GuardRecoveryEdit()
1508 {
1509 if (CurrentCaseId <= 0)
1510 {
1511 FnfPanel.JSProperties["cpMsg"] = "Open a case first.";
1512 RecoveryGrid.CancelEdit();
1513 return false;
1514 }
1515
1516 if (!FNFCaseService.CanEdit(CurrentStatus))
1517 {
1518 FnfPanel.JSProperties["cpMsg"] = "This case can no longer be changed.";
1519 RecoveryGrid.CancelEdit();
1520 return false;
1521 }
1522
1523 return true;
1524 }
