725	   725	    /// A manual-row insert/update/delete triggers only a re-total, NOT a full Calculate() - a
726	   726	    /// full recalculate would also re-read leave/loans/assets and discard the figure the user
727	   727	    /// just typed. Re-sums ALL current lines (auto + manual) by Add/Deduct.
728	   728	    /// </summary>
729	   729	    private async Task LightweightRetotalAsync(long caseId)
730	   730	    {
731	   731	        var details = await _repository.GetSettlementDetailsAsync(caseId);
732	   732	        var earnings = details.Where(d => d.AddDeduct == "Add").Sum(d => d.Amount);
733	   733	        var deductions = details.Where(d => d.AddDeduct == "Deduct").Sum(d => d.Amount);
