737	   737	        await _repository.UpdateHeaderCalculationResultsAsync(caseId,
738	   738	            caseHeader?.PerDayRate ?? 0, caseHeader?.PerDayRateBasis ?? string.Empty,
739	   739	            caseHeader?.LeaveEncashDays ?? 0, caseHeader?.LeaveEncashAmount ?? 0, caseHeader?.GratuityAmount ?? 0,
740	   740	            earnings, deductions, netPayable);
741	   741	    }
