743	   743	    /// <summary>
744	   744	    /// Approval Engine gate (docs/dev-tracking/approval.md Phase 11) - real, new authorization
745	   745	    /// where none existed before (see the class remarks: today's ApproveAsync/RejectAsync have zero
746	   746	    /// decision-level auth beyond [Authorize] + company scoping). Returns null to proceed with the
747	   747	    /// legacy write, or the (status, message) to refuse the request with.
748	   748	    /// </summary>
749	   749	    private async Task<(HttpStatusCode Status, string Message)?> ApplyApprovalEngineGateAsync(long caseId, string decision, string? remarks)
750	   750	    {
751	   751	        var formDocId = await _approvalService.ResolveFormDocIdAsync(ApprovalModuleKeys.Fnf, FnfFormDocNames.Approval);
752	   752	        var instanceId = formDocId is null ? null : await _approvalService.GetInstanceIdAsync(formDocId.Value, caseId);
753	   753	        if (instanceId is null) return null;
754	   754	
755	   755	        var actionResult = await _approvalService.Action(new ApprovalActionModel
756	   756	        {
757	   757	            ApprovalInstanceId = instanceId.Value,
758	   758	            EmployeeId = _requestMetadata.EmployeeMasterId,
759	   759	            Decision = decision,
760	   760	            Remarks = remarks,
761	   761	        });
762	   762	
763	   763	        if (actionResult.IsSuccess) return null;
764	   764	
765	   765	        if (actionResult.Status == HttpStatusCode.Conflict)
766	   766	        {
767	   767	            // Most likely a stale instance from a prior reject-then-resubmit cycle for this same
768	   768	            // caseId (TryCreateApprovalInstanceAsync could not create a fresh one on resubmission -
769	   769	            // HR_ApprovalInstance has no "reopen" concept, same precedent as Recruitment's Reopen
770	   770	            // transitions bypassing the engine entirely). Not a real double-decision race: the
771	   771	            // WorkflowStatus check the caller already ran, plus ApproveCaseHeaderAsync/
772	   772	            // RejectCaseAsync's own `rows == 0` optimistic-concurrency guard, already catch two
773	   773	            // people deciding the SAME live pending case - so falling through here instead of
774	   774	            // hard-blocking is safe.
775	   775	            _logger.LogInformation(
776	   776	                "F&F case {CaseId}: approval engine instance already closed (likely stale from a prior reject/resubmit cycle) - falling through to the existing WorkflowStatus check.",
777	   777	                caseId);
778	   778	            return null;
779	   779	        }
780	   780	
781	   781	        return (actionResult.Status, actionResult.Message);
782	   782	    }
