814	   814	                CompanyMasterId = companyMasterId,
815	   815	                BranchMasterId = null,
816	   816	            });
817	   817	
818	   818	            if (!result.IsSuccess || result.Data == null)
819	   819	                _logger.LogWarning("Could not create approval instance for F&F case {CaseId}: {Message}", caseId, result.Message);
820	   820	        }
821	   821	        catch (Exception ex)
822	   822	        {
