536	    public async Task<ResponseModel> UpdateCheckResultAsync(long caseId, UpdateCheckResultModel model)
537	    {
538	        var res = new ResponseModel();
539	        var companyId = _requestMetadata.CompanyId;
540	        try
541	        {
542	            var existing = await _repository.GetCaseByIdAsync(caseId, companyId);
543	            if (existing == null) return Fail(res, HttpStatusCode.NotFound, "F&F case not found.");
544	
545	            // The check's own row carries its kind, so none is passed here. Passing a literal
546	            // "Readiness" - as this did - meant Verification and Handover checks matched no row
547	            // and could never be answered, which left every case stuck in Draft.
548	            await _repository.UpdateCheckResultAsync(model.FnfCheckId, caseId, model.Result, model.Remarks, _requestMetadata.UserId);
549	            await EvaluateClearanceAsync(caseId);
550	            return Success(res, "Updated.");
551	        }
552	        catch (Exception e)
553	        {
554	            _logger.LogError(e, "Exception while updating check {Id}", model.FnfCheckId);
555	            return Fail(res, HttpStatusCode.InternalServerError, e.Message);
556	        }
557	    }
