576	    public async Task<ResponseModel> AddRecoveryAsync(AddRecoveryModel model)
577	    {
578	        var res = new ResponseModel();
579	        try
580	        {
581	            var newId = await _repository.AddRecoveryAsync(model, _requestMetadata.UserId, _requestMetadata.CompanyId);
582	            return Success(res, "Recovery added.", new { id = newId });
583	        }
584	        catch (Exception e)
585	        {
586	            _logger.LogError(e, "Exception while adding recovery to case {Id}", model.FnfSettlementId);
587	            return Fail(res, HttpStatusCode.InternalServerError, e.Message);
588	        }
