591	    public async Task<ResponseModel> UpdateRecoveryAsync(long caseId, UpdateRecoveryModel model)
592	    {
593	        var res = new ResponseModel();
594	        try
595	        {
596	            var existing = await _repository.GetRecoveryByIdAsync(model.FnfRecoveryId, caseId);
597	            if (existing == null) return Fail(res, HttpStatusCode.NotFound, "Recovery not found.");
598	            await _repository.UpdateRecoveryAsync(model, _requestMetadata.UserId);
599	            return Success(res, "Recovery updated.");
600	        }
601	        catch (Exception e)
602	        {
