608	    public async Task<ResponseModel> DeleteRecoveryAsync(long caseId, long recoveryId)
609	    {
610	        var res = new ResponseModel();
611	        try
612	        {
613	            var existing = await _repository.GetRecoveryByIdAsync(recoveryId, caseId);
614	            if (existing == null) return Fail(res, HttpStatusCode.NotFound, "Recovery not found.");
615	            // Soft delete, on purpose: the next Recheck's auto-discovery must never immediately
616	            // resurrect a row someone just waived/deleted.
617	            await _repository.SoftDeleteRecoveryAsync(recoveryId, _requestMetadata.UserId);
618	            return Success(res, "Recovery removed.");
619	        }
620	        catch (Exception e)
621	        {
622	            _logger.LogError(e, "Exception while deleting recovery {Id}", recoveryId);
623	            return Fail(res, HttpStatusCode.InternalServerError, e.Message);
