  1	using Microsoft.Extensions.Logging;
  2	using SolutionOne_BusinessLogicLayer.Services.Payroll.Interface;
  3	using SolutionOne_Core.PayrollModels;
  4	using SolutionOne_DataAccessLayer.Repositories.Payroll.Interface;
  5	
  6	namespace SolutionOne_BusinessLogicLayer.Services.Payroll.Implementation;
  7	
  8	/// <summary>
  9	/// The Full &amp; Final money calculation. Ported from the legacy FNFSettlementService.Calculate.
 10	/// Has NO dependency on IFnfCaseService — see 05_FNFSettlementApproval.md §3.
 11	/// </summary>
 12	public class FnfCalculationService(
 13	    IFnfSettlementRepository repository,
 14	    IFnfConfigRepository configRepository,
 15	    IAlumniRepository alumniRepository,
 16	    ILogger<FnfCalculationService> logger
 17	) : IFnfCalculationService
 18	{
 19	    private readonly IFnfSettlementRepository _repository = repository;
 20	    private readonly IFnfConfigRepository _configRepository = configRepository;
 21	    private readonly IAlumniRepository _alumniRepository = alumniRepository;
 22	    private readonly ILogger<FnfCalculationService> _logger = logger;
 23	
 24	    private static decimal Round2(decimal v) => Math.Round(v, 2, MidpointRounding.AwayFromZero);
 25	
 26	    private static decimal PickBase(string baseName, decimal basic, decimal gross, decimal ctc) =>
 27	        baseName?.Trim().ToUpperInvariant() switch
 28	        {
 29	            "GROSS" => gross,
 30	            "CTC" => ctc,
 31	            _ => basic, // "Basic", "Basic+DA" (no separate DA column in this schema) and anything unrecognized
 32	        };
 33	
 34	    private static long? HeadFor(string componentType, FnfConfigModel config) => componentType switch
 35	    {
 36	        "Gratuity" => config.GratuityHeadId,
 37	        "LeaveEncashment" => config.LeaveEncashHeadId,
 38	        "NoticePay" => config.NoticePayHeadId,
 39	        "NoticeRecovery" => config.NoticeRecoveryHeadId,
 40	        "AssetRecovery" => config.AssetRecoveryHeadId,
 41	        "OtherRecovery" => config.AssetRecoveryHeadId, // shares Asset's head - no head of its own
 42	        "LoanRecovery" => config.LoanRecoveryHeadId,
 43	        _ => null, // FinalSalary never pushed anyway
 44	    };
 45	
 46	    private static bool IsPushable(string componentType) => componentType != "FinalSalary";
 47	
 48	    public async Task<FnfConfigModel> LoadConfigAsync(long companyMasterId)
 49	    {
 50	        var config = await _configRepository.GetConfigAsync(companyMasterId);
 51	        if (config == null)
 52	            throw new InvalidOperationException($"No F&F configuration exists for company {companyMasterId}.");
 53	        return config;
 54	    }
 55	
 56	    public async Task<FnfCalculationResult> CalculateAsync(long caseId, long companyMasterId, bool persist)
 57	    {
 58	        var result = new FnfCalculationResult();
 59	
 60	        var caseHeader = await _repository.GetCaseByIdAsync(caseId, companyMasterId)
 61	            ?? throw new InvalidOperationException($"F&F case {caseId} not found.");
 62	        var config = await LoadConfigAsync(companyMasterId);
 63	
 64	        var salary = await _repository.GetSalaryStructureAsync(caseHeader.EmployeeMasterId);
 65	        var basic = salary?.Basic ?? 0m;
 66	        var gross = salary?.Gross ?? 0m;
 67	        var ctc = salary?.Ctc ?? 0m;
 68	        if (salary == null)
 69	            result.Notes.Add("No basic salary record found - every rate-based component is zero.");
 70	
 71	        // -- Per-day rate --
 72	        var rateBase = PickBase(config.PerDayRateBase, basic, gross, ctc);
 73	        decimal divisor;
 74	        if (string.Equals(config.PerDayRateDivisorType, "Fixed", StringComparison.OrdinalIgnoreCase))
 75	        {
 76	            divisor = config.PerDayRateDivisorValue > 0 ? config.PerDayRateDivisorValue : 26;
 77	            result.PerDayRateBasis = $"{config.PerDayRateBase} / {divisor:0.##}";
 78	        }
 79	        else if (caseHeader.LastWorkingDate.HasValue)
 80	        {
 81	            var attendance = await _repository.GetMonthlyAttendanceAsync(caseHeader.EmployeeMasterId,
 82	                caseHeader.LastWorkingDate.Value.Month, caseHeader.LastWorkingDate.Value.Year);
 83	            var value = string.Equals(config.PerDayRateDivisorType, "WorkingDays", StringComparison.OrdinalIgnoreCase)
 84	                ? attendance?.WorkingDays : attendance?.MonthDays;
 85	            if (value.HasValue && value.Value > 0)
 86	            {
 87	                divisor = value.Value;
 88	                result.PerDayRateBasis = $"{config.PerDayRateBase} / {config.PerDayRateDivisorType} ({divisor:0.##})";
 89	            }
 90	            else
 91	            {
 92	                divisor = config.PerDayRateDivisorValue > 0 ? config.PerDayRateDivisorValue : 26;
 93	                result.PerDayRateBasis = $"{config.PerDayRateBase} / {divisor:0.##} (fallback - no attendance figure for the final month)";
 94	                result.Notes.Add("No attendance record for the final month - a divisor of zero would make every rate-based component zero without saying why, so the fixed divisor was used instead.");
 95	            }
 96	        }
 97	        else
 98	        {
 99	            divisor = config.PerDayRateDivisorValue > 0 ? config.PerDayRateDivisorValue : 26;
100	            result.PerDayRateBasis = $"{config.PerDayRateBase} / {divisor:0.##} (fallback - no last working date)";
101	        }
102	        result.PerDayRate = divisor > 0 ? Round2(rateBase / divisor) : 0;
103	
104	        await AddFinalSalary(caseHeader, result);
105	        await AddLeaveEncashment(caseHeader, config, result);
106	        AddGratuity(caseHeader, config, basic, gross, ctc, result);
107	        AddNoticeRecovery(caseHeader, result);
108	        await AddClearanceRecoveries(caseId, config, result);
109	
110	        result.TotalEarnings = result.Components.Where(c => c.AddDeduct == "Add").Sum(c => c.Amount);
111	        result.TotalDeductions = result.Components.Where(c => c.AddDeduct == "Deduct").Sum(c => c.Amount);
112	        result.NetPayable = result.TotalEarnings - result.TotalDeductions;
113	        if (result.NetPayable < 0)
114	            result.Notes.Add("Settlement is RECOVERABLE from the employee.");
115	
116	        if (persist)
117	            await PersistInternalAsync(caseId, result);
118	
119	        return result;
120	    }
121	
122	    private async Task AddFinalSalary(FnfCaseModel caseHeader, FnfCalculationResult result)
123	    {
124	        if (caseHeader.LastWorkingDate == null)
125	        {
126	            result.Notes.Add("No last working date - the final month's salary line was not added.");
127	            return;
128	        }
129	
130	        var net = await _repository.GetFinalNetPayAsync(caseHeader.EmployeeMasterId,
131	            caseHeader.LastWorkingDate.Value.Month, caseHeader.LastWorkingDate.Value.Year);
132	
133	        if (!net.HasValue || net.Value <= 0)
134	        {
135	            result.Components.Add(new FnfCalculationLine
136	            {
137	                ComponentType = "FinalSalary", AddDeduct = "Add", Amount = 0,
138	                Remarks = "Run Confirm Pay and Salary Generate for that month, then recalculate.",
139	            });
140	            result.Notes.Add("Final month's salary is not yet confirmed in payroll - shown as 0.");
141	            return;
142	        }
143	
144	        result.Components.Add(new FnfCalculationLine { ComponentType = "FinalSalary", AddDeduct = "Add", Amount = net.Value });
145	    }
146	
147	    private async Task AddLeaveEncashment(FnfCaseModel caseHeader, FnfConfigModel config, FnfCalculationResult result)
148	    {
149	        var (days, typeCount) = await _repository.GetEncashableLeaveBalanceAsync(caseHeader.EmployeeMasterId, caseHeader.CompanyMasterId);
150	
151	        if (typeCount == 0)
152	        {
153	            result.Notes.Add("Tick Is Encashable on the leave types in F&F Configuration - no encashable leave type is configured, so no line was added.");
154	            return;
155	        }
156	
157	        var preCapDays = days;
158	        if (config.EncashmentCapDays.HasValue && days > config.EncashmentCapDays.Value)
159	        {
160	            days = config.EncashmentCapDays.Value;
161	            result.Notes.Add($"Encashment capped at {days:0.##} days (was {preCapDays:0.##} before the cap).");
162	        }
163	
164	        var amount = Round2(days * result.PerDayRate);
165	        result.LeaveEncashDays = days;
166	        result.LeaveEncashAmount = amount;
167	        result.Components.Add(new FnfCalculationLine
168	        {
169	            ComponentType = "LeaveEncashment", AddDeduct = "Add", Days = days, Rate = result.PerDayRate,
170	            Amount = amount, SalaryHeadMasterId = config.LeaveEncashHeadId,
171	        });
172	    }
173	
174	    private static void AddGratuity(FnfCaseModel caseHeader, FnfConfigModel config, decimal basic, decimal gross,
175	        decimal ctc, FnfCalculationResult result)
176	    {
177	        if (!config.GratuityEnabled)
178	        {
179	            result.Notes.Add("Gratuity is switched off in F&F Configuration.");
180	            return;
181	        }
182	        if (caseHeader.DateOfJoining == null || caseHeader.LastWorkingDate == null)
183	        {
184	            result.Notes.Add("Gratuity could not be computed - date of joining or last working date is missing.");
185	            return;
186	        }
187	
188	        // *** Compare the FRACTIONAL served-years figure against the threshold, never the
189	        // floored one - someone at exactly 5.0 years passes, 4.99 does not, and a naive floored
190	        // comparison would wrongly treat both as "5 years." Floor only for the multiplier below.
191	        var servedYears = (decimal)(caseHeader.LastWorkingDate.Value - caseHeader.DateOfJoining.Value).TotalDays / 365.25m;
192	        var completedYears = Math.Floor(servedYears);
193	
194	        if (servedYears < config.GratuityEligibleYears)
195	        {
196	            result.Notes.Add($"Not yet eligible for gratuity - {servedYears:0.00} years served, {config.GratuityEligibleYears:0.##} required.");
197	            return;
198	        }
199	
200	        var gratuityBase = PickBase(config.GratuityBase, basic, gross, ctc);
201	        var divisor = config.GratuityDivisor > 0 ? config.GratuityDivisor : 26;
202	        var amount = Round2(gratuityBase / divisor * config.GratuityDaysPerYear * completedYears);
203	
204	        result.GratuityAmount = amount;
205	        result.Components.Add(new FnfCalculationLine
206	        {
207	            ComponentType = "Gratuity", AddDeduct = "Add", Amount = amount, SalaryHeadMasterId = config.GratuityHeadId,
208	        });
209	    }
210	
211	    private static void AddNoticeRecovery(FnfCaseModel caseHeader, FnfCalculationResult result)
212	    {
213	        if (caseHeader.NoticeDaysRequired == null)
214	        {
215	            // "Nobody has said" is not the same fact as "0 days required" - no line, no note.
216	            return;
217	        }
218	        if (caseHeader.ResignDate == null || caseHeader.LastWorkingDate == null)
219	            return;
220	
221	        var served = Math.Max(0, (decimal)(caseHeader.LastWorkingDate.Value - caseHeader.ResignDate.Value).TotalDays);
222	        var shortfall = caseHeader.NoticeDaysRequired.Value - served;
223	        if (shortfall <= 0)
224	            return;
