122	    private async Task AddFinalSalary(FnfCaseModel caseHeader, FnfCalculationResult result)
123	    {
124	        if (caseHeader.LastWorkingDate == null)
125	        {
126	            result.Notes.Add("No last working date - the final month's salary line was not added.");
127	            return;
128	        }
129	
130	        var net = await _repository.GetFinalNetPayAsync(caseHeader.EmployeeMasterId,
131	            caseHeader.LastWorkingDate.Value.Month, caseHeader.LastWorkingDate.Value.Year);
132	
133	        if (!net.HasValue || net.Value <= 0)
134	        {
135	            result.Components.Add(new FnfCalculationLine
136	            {
137	                ComponentType = "FinalSalary", AddDeduct = "Add", Amount = 0,
138	                Remarks = "Run Confirm Pay and Salary Generate for that month, then recalculate.",
139	            });
140	            result.Notes.Add("Final month's salary is not yet confirmed in payroll - shown as 0.");
141	            return;
142	        }
143	
144	        result.Components.Add(new FnfCalculationLine { ComponentType = "FinalSalary", AddDeduct = "Add", Amount = net.Value });
145	    }
