174	    private static void AddGratuity(FnfCaseModel caseHeader, FnfConfigModel config, decimal basic, decimal gross,
175	        decimal ctc, FnfCalculationResult result)
176	    {
177	        if (!config.GratuityEnabled)
178	        {
179	            result.Notes.Add("Gratuity is switched off in F&F Configuration.");
180	            return;
181	        }
182	        if (caseHeader.DateOfJoining == null || caseHeader.LastWorkingDate == null)
183	        {
184	            result.Notes.Add("Gratuity could not be computed - date of joining or last working date is missing.");
185	            return;
186	        }
187	
188	        // *** Compare the FRACTIONAL served-years figure against the threshold, never the
189	        // floored one - someone at exactly 5.0 years passes, 4.99 does not, and a naive floored
190	        // comparison would wrongly treat both as "5 years." Floor only for the multiplier below.
191	        var servedYears = (decimal)(caseHeader.LastWorkingDate.Value - caseHeader.DateOfJoining.Value).TotalDays / 365.25m;
192	        var completedYears = Math.Floor(servedYears);
193	
194	        if (servedYears < config.GratuityEligibleYears)
195	        {
196	            result.Notes.Add($"Not yet eligible for gratuity - {servedYears:0.00} years served, {config.GratuityEligibleYears:0.##} required.");
197	            return;
198	        }
199	
200	        var gratuityBase = PickBase(config.GratuityBase, basic, gross, ctc);
201	        var divisor = config.GratuityDivisor > 0 ? config.GratuityDivisor : 26;
202	        var amount = Round2(gratuityBase / divisor * config.GratuityDaysPerYear * completedYears);
203	
204	        result.GratuityAmount = amount;
205	        result.Components.Add(new FnfCalculationLine
206	        {
207	            ComponentType = "Gratuity", AddDeduct = "Add", Amount = amount, SalaryHeadMasterId = config.GratuityHeadId,
208	        });
209	    }
