299	            ("SAL_ATT", "Final salary amount", AmountOf("FinalSalary")),
300	            ("ENCASH", "Leave encashment amount", result.LeaveEncashAmount),
301	            ("GRATUITY", "Gratuity amount", result.GratuityAmount),
302	            ("BONUS", "Bonus", 0m),
303	            ("DEDUCTIONS", "Total deductions", result.TotalDeductions),
304	            ("LOAN_RECON", "Loan recovery amount", loanRecovery),
305	            ("TAX", "Tax", 0m),
306	            ("NET_FORMULA", "Net payable", result.NetPayable),
307	        };
308	        var sortOrder = 10;
309	        foreach (var (code, name, value) in verification)
310	        {
311	            await _repository.UpsertCheckAsync(caseId, "Verification", code, name, isRequired: true,
312	                policyStandard: null, actualValue: value.ToString("0.00"), sortOrder);
313	            sortOrder += 10;
314	        }
315	
316	        var handover = new[] { "PAYMENT", "STATEMENT", "TAXDOC", "RELIEVING", "EXPERIENCE", "PFFORM", "DECLARE", "ASSETS" };
317	        var handoverNames = new Dictionary<string, string>
318	        {
319	            ["PAYMENT"] = "Payment released", ["STATEMENT"] = "Statement handed over", ["TAXDOC"] = "Form 16 / tax document issued",
320	            ["RELIEVING"] = "Relieving letter issued", ["EXPERIENCE"] = "Experience letter issued", ["PFFORM"] = "PF withdrawal form issued",
321	            ["DECLARE"] = "Full & Final declaration signed", ["ASSETS"] = "Assets fully returned",
322	        };
323	        sortOrder = 10;
324	        foreach (var code in handover)
325	        {
326	            await _repository.UpsertCheckAsync(caseId, "Handover", code, handoverNames[code], isRequired: true,
327	                policyStandard: null, actualValue: null, sortOrder);
328	            sortOrder += 10;
329	        }
330	    }
331	
332	    public async Task SeedApprovalParametersAsync(long caseId, long companyMasterId)
333	    {
334	        var result = await CalculateAsync(caseId, companyMasterId, persist: false);
335	        var config = await LoadConfigAsync(companyMasterId);
336	
337	        var gratuityPolicy = config.GratuityEnabled
338	            ? $"{config.GratuityEligibleYears:0.##} years, {config.GratuityDaysPerYear:0.##} days/yr on {config.GratuityBase}, /{config.GratuityDivisor:0.##}"
339	            : "switched off";
340	        var encashPolicy = config.EncashmentCapDays.HasValue ? $"capped at {config.EncashmentCapDays:0.##} days" : "no cap configured";
341	        var loanRecovery = result.Components.Where(c => c.ComponentType == "LoanRecovery").Sum(c => c.Amount);
342	        var totalRecoveries = result.Components.Where(c => c.ComponentType is "LoanRecovery" or "AssetRecovery" or "OtherRecovery").Sum(c => c.Amount);
343	
344	        // Each row carries its own display name. The code was previously passed for both, so the
345	        // approver's checklist read "AP_GRATUITY" / "AP_ENCASH" - the internal keys - rather than
346	        // saying what was being confirmed.
347	        var rows = new[]
348	        {
349	            ("AP_GRATUITY", "Gratuity amount", gratuityPolicy, result.GratuityAmount),
350	            ("AP_ENCASH",   "Leave encashment amount", encashPolicy, result.LeaveEncashAmount),
351	            ("AP_NOTICE",   "Notice-period recovery", (string?)null,
352	                result.Components.Where(c => c.ComponentType == "NoticeRecovery").Sum(c => c.Amount)),
353	            ("AP_RECOVERY", "Total recoveries", null, totalRecoveries),
354	            ("AP_NET",      "Net payable", null, result.NetPayable),
355	        };
356	        var sortOrder = 10;
357	        foreach (var (code, name, policy, value) in rows)
358	        {
359	            await _repository.UpsertCheckAsync(caseId, "ApprovalParameter", code, name, isRequired: true,
360	                policyStandard: policy, actualValue: value.ToString("0.00"), sortOrder);
361	            sortOrder += 10;
362	        }
363	    }
364	
365	    public async Task<int> PushToPayrollAsync(long caseId, long employeeMasterId, long companyMasterId, int month, int year)
366	    {
367	        var config = await LoadConfigAsync(companyMasterId);
368	        var current = await _repository.GetCurrentCategoryBranchAsync(employeeMasterId);
369	        var categoryMasterId = current?.CategoryMasterId ?? 0;
370	        var branchMasterId = current?.BranchMasterId ?? 0;
371	
372	        var details = await _repository.GetSettlementDetailsAsync(caseId);
373	        var grouped = details
374	            .Where(d => IsPushable(d.ComponentType) && d.Amount != 0)
375	            .GroupBy(d => (d.ComponentType, d.SalaryHeadMasterId, d.AddDeduct))
376	            .Select(g => new { g.Key.ComponentType, g.Key.SalaryHeadMasterId, g.Key.AddDeduct, Amount = g.Sum(x => x.Amount) });
377	
378	        var pushed = 0;
379	        foreach (var group in grouped)
380	        {
381	            var headId = group.SalaryHeadMasterId ?? HeadFor(group.ComponentType, config)
382	                ?? throw new InvalidOperationException($"No salary head configured for {group.ComponentType} - set it in F&F Configuration.");
383	
384	            await _repository.EnsureEmployeeHeadAsync(employeeMasterId, headId, categoryMasterId, branchMasterId, companyMasterId);
385	            await _repository.UpsertAdditionalHeadAsync(employeeMasterId, headId, group.Amount, $"F&F settlement - {group.ComponentType}",
386	                month, year, categoryMasterId, branchMasterId);
387	            pushed++;
388	        }
389	
390	        await _repository.StampSettlementMonthYearAsync(caseId, month, year);
391	        return pushed;
392	    }
393	
394	    public async Task SettleLoanScheduleAsync(long caseId, long employeeMasterId)
395	    {
396	        var details = await _repository.GetSettlementDetailsAsync(caseId);
397	        if (details.Any(d => d.ComponentType == "LoanRecovery" && d.Amount > 0))
398	            await _repository.MarkLoanScheduleSettledAsync(employeeMasterId);
399	    }
400	
401	    public async Task RecordAcceptanceAsync(long caseId, long employeeMasterId, long companyMasterId,
402	        string acceptanceResult, string? remarks, long userId)
403	    {
404	        await _repository.RecordAcceptanceAsync(caseId, acceptanceResult, remarks);
405	
406	        // Reuses guide 02's own guard - never a second, duplicate check. Exit Formality is a
407	        // separate module this port does not build (05_FNFSettlementApproval.md §2) - reason/
408	        // feedback are left null here rather than reading a table that may not exist yet.
409	        if (!await _alumniRepository.HasLiveRecordAsync(employeeMasterId, excludeAlumniId: 0))
410	        {
411	            await _alumniRepository.AddFromSettlementAsync(employeeMasterId, caseId,
412	                reasonForLeaving: null, managerFeedback: null, userId, companyMasterId);
413	        }
414	    }
415	
416	    public async Task<string?> ChecklistIncompleteReasonAsync(long caseId, string checkKind, string label)
417	    {
418	        var total = await _repository.CountChecksAsync(caseId, checkKind);
419	        if (total == 0)
420	            return $"the {label} checklist is empty, so nothing has actually been checked. Send the case back to the preparer to run Calculate.";
421	
422	        var firstFailing = await _repository.GetFirstIncompleteRequiredCheckAsync(caseId, checkKind);
423	        return firstFailing == null ? null : $"{firstFailing.Value.CheckName} is {firstFailing.Value.Result ?? "not checked"}.";
424	    }
425	}

