  1	using SolutionOne_Core.PayrollModels;
  2	using SolutionOne_DataAccessLayer.Repositories.Common.Interface;
  3	using SolutionOne_DataAccessLayer.Repositories.Payroll.Interface;
  4	
  5	namespace SolutionOne_DataAccessLayer.Repositories.Payroll.Implementation;
  6	
  7	/// <summary>
  8	/// HR_FNFSettlement + HR_FNFSettlementDetail + HR_FNFCheck + HR_FNFRecovery data access, Dapper.
  9	/// </summary>
 10	/// <remarks>
 11	/// Schema confirmed directly against hr_payroll migrations 110/111/113/114 for every FNF table,
 12	/// HR_EmployeeMaster, HR_EmployeeBasicSalary, HR_MonthlyAttendance, HR_PayrollSalaryConfirmation,
 13	/// HR_EmployeeWiseLeave, HR_EmployeeWiseSalaryHead and HR_SalaryAdditionalHead (cross-checked
 14	/// against their EF entities/Fluent mappings even though this repository is Dapper, not EF).
 15	///
 16	/// NOT cross-checked, flagged explicitly: HR_LoanEMISchedule and the Assets tables
 17	/// (HR_AssetIssue/HR_AssetIssueDetail/HR_AssetReturn) have no EF entity in this codebase to verify
 18	/// against. GetOutstandingLoanAsync/MarkLoanScheduleSettledAsync use the exact column names
 19	/// 05_FNFSettlementApproval.md gives (itself written from a full read of the legacy
 20	/// FNFSettlementService.cs) - verify against the live schema before relying on these two methods.
 21	/// </remarks>
 22	public class FnfSettlementRepository(IDapperContext tx, IDapperRepository repo) : IFnfSettlementRepository
 23	{
 24	    private readonly IDapperContext _tx = tx;
 25	    private readonly IDapperRepository _repo = repo;
 26	
 27	    private const string _CaseSelectSql = @"
 28	        SELECT f.FNFSettlementID AS FnfSettlementId, f.CaseNo, f.EmployeeMasterID AS EmployeeMasterId,
 29	               ISNULL(LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(em.FirstName)),''), '')
 30	                          + ISNULL(' ' + NULLIF(LTRIM(RTRIM(em.FatherName)),''), '')
 31	                          + ISNULL(' ' + NULLIF(LTRIM(RTRIM(em.LastName)),''), '')), '') AS EmployeeName,
 32	               ISNULL(em.Code, '') AS EmployeeCode,
 33	               f.CaseDate, f.ResignDate, f.LastWorkingDate, f.SettlementDate, f.DateOfJoining,
 34	               f.DepartmentMasterID AS DepartmentMasterId, f.DesignationMasterID AS DesignationMasterId,
 35	               f.ReportingPersonID AS ReportingPersonId, f.CasePriority, f.WorkflowStatus,
 36	               f.ExitFormalityID AS ExitFormalityId,
 37	               f.PlannedCalcStartDate, f.PlannedSettlementDate, f.ActualCalcStartDate, f.ApprovalTurnaroundDays,
 38	               f.HRExecutiveUserMasterID AS HrExecutiveUserMasterId,
 39	               f.PayrollExecutiveUserMasterID AS PayrollExecutiveUserMasterId,
 40	               f.FinanceExecutiveUserMasterID AS FinanceExecutiveUserMasterId,
 41	               f.ApproverUserMasterID AS ApproverUserMasterId,
 42	               f.NoticeDaysRequired, f.NoticeDaysServed,
 43	               f.PerDayRate, f.PerDayRateBasis, f.LeaveEncashDays, f.LeaveEncashAmount, f.GratuityAmount,
 44	               f.TotalEarnings, f.TotalDeductions, f.NetPayable,
 45	               f.IsClearanceReady, f.ClearanceBlockReason,
 46	               f.SettlementMonth, f.SettlementYear,
 47	               f.AcceptanceResult, f.AcceptanceRemarks, f.AcceptedOn, f.StatementSharedOn,
 48	               f.ComplianceWindowDays, f.ComplianceWindowStart, f.ComplianceWindowEnd,
 49	               f.Remarks, f.CategoryMasterID AS CategoryMasterId, f.BranchMasterID AS BranchMasterId,
 50	               f.CompanyMasterID AS CompanyMasterId
 51	        FROM   HR_FNFSettlement f
 52	        LEFT   JOIN HR_EmployeeMaster em ON em.EmployeeMasterID = f.EmployeeMasterID";
 53	
 54	    // ---------------------------------------------------------------- Eligibility / case CRUD --
 55	
 56	    public async Task<List<EligibleEmployeeModel>> GetEligibleEmployeesAsync(long companyMasterId, bool requireExitFormality)
 57	    {
 58	        var sql = @"
 59	            SELECT em.EmployeeMasterID AS EmployeeMasterId,
 60	                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(em.FirstName)),''), '')
 61	                       + ISNULL(' ' + NULLIF(LTRIM(RTRIM(em.FatherName)),''), '')
 62	                       + ISNULL(' ' + NULLIF(LTRIM(RTRIM(em.LastName)),''), '')) AS EmployeeName,
 63	                   ISNULL(em.Code, '') AS EmployeeCode
 64	            FROM   HR_EmployeeMaster em
 65	            WHERE  em.CompanyMasterID = @CompanyMasterId AND em.Status = 1
 66	              AND  ( (em.ResignDate IS NOT NULL AND em.ResignDate > '1900-01-01')
 67	                  OR (em.DateOfLeft IS NOT NULL AND em.DateOfLeft > '1900-01-01') )
 68	              AND  NOT EXISTS (SELECT 1 FROM HR_FNFSettlement f
 69	                               WHERE f.EmployeeMasterID = em.EmployeeMasterID
 70	                                 AND f.Status = 1 AND f.WorkflowStatus <> 'Cancelled')";
 71	
 72	        if (requireExitFormality)
 73	        {
 74	            sql += @"
 75	              AND  EXISTS (SELECT 1 FROM HR_ExitFormality x
 76	                          WHERE x.EmployeeMasterID = em.EmployeeMasterID AND x.Status = 1 AND x.IsComplete = 1)";
 77	        }
 78	
 79	        var res = await _repo.QueryAsync<EligibleEmployeeModel>(sql, new { CompanyMasterId = companyMasterId });
 80	        return res.ToList();
 81	    }
 82	
 83	    public async Task<(DateTime? ResignDate, DateTime? DateOfLeft, DateTime? DateOfJoining, long? DepartmentMasterId,
 84	        long? DesignationMasterId, long? ReportingPersonId, int? NoticePeriodDays, long? ExitFormalityId)?>
 85	        GetEmployeeSnapshotAsync(long employeeMasterId, long companyMasterId)
 86	    {
 87	        // NoticePeriodDays does not exist on HR_EmployeeMaster. The column is NoticePeriod, and it
 88	        // is nvarchar free text - so it holds "30" on some tenants and "1 Month" or nothing on
 89	        // others. TRY_CONVERT yields the number when it is one and NULL when it is not, which is
 90	        // exactly what an int? notice period should be: a value, or "not recorded". Reading it
 91	        // raw threw "Invalid column name 'NoticePeriodDays'" and broke the whole MakeCase handoff
 92	        // from Exit Formality into settlement.
 93	        // TRY_CONVERT is SQL 2012+, so this stays 2014-safe.
 94	        const string sql = @"
 95	            SELECT em.ResignDate, em.DateOfLeft, em.DateOfJoining, em.DepartmentMasterID, em.DesignationMasterID,
 96	                   em.ReportingPersonID,
 97	                   TRY_CONVERT(int, LTRIM(RTRIM(em.NoticePeriod))) AS NoticePeriodDays,
 98	                   (SELECT TOP 1 x.ExitFormalityID FROM HR_ExitFormality x
 99	                    WHERE x.EmployeeMasterID = em.EmployeeMasterID AND x.Status = 1
100	                    ORDER BY x.ExitFormalityID DESC) AS ExitFormalityId
101	            FROM   HR_EmployeeMaster em
102	            WHERE  em.EmployeeMasterID = @EmployeeMasterId AND em.CompanyMasterID = @CompanyMasterId";
103	
104	        var row = await _repo.QueryFirstOrDefaultAsync<EmployeeSnapshotRow>(sql,
105	            new { EmployeeMasterId = employeeMasterId, CompanyMasterId = companyMasterId });
106	        return row == null ? null : (row.ResignDate, row.DateOfLeft, row.DateOfJoining, row.DepartmentMasterId,
107	            row.DesignationMasterId, row.ReportingPersonId, row.NoticePeriodDays, row.ExitFormalityId);
108	    }
109	
110	    private class EmployeeSnapshotRow
111	    {
112	        public DateTime? ResignDate { get; set; }
113	        public DateTime? DateOfLeft { get; set; }
114	        public DateTime? DateOfJoining { get; set; }
115	        public long? DepartmentMasterId { get; set; }
116	        public long? DesignationMasterId { get; set; }
117	        public long? ReportingPersonId { get; set; }
118	        public int? NoticePeriodDays { get; set; }
119	        public long? ExitFormalityId { get; set; }
120	    }
121	
122	    public async Task<int> GetMaxCaseNumberForYearAsync(int year)
123	    {
124	        // WITH (UPDLOCK, HOLDLOCK): the row lock that stops two concurrent creates computing the
125	        // same next number. Must run inside the caller's already-open transaction.
126	        const string sql = @"
127	            SELECT ISNULL(MAX(TRY_CONVERT(int, RIGHT(CaseNo, 5))), 0)
128	            FROM   HR_FNFSettlement WITH (UPDLOCK, HOLDLOCK)
129	            WHERE  CaseNo LIKE 'FNF-' + CAST(@Year AS varchar(4)) + '-%'";
130	        return await _repo.ExecuteScalarAsync<int>(sql, new { Year = year });
131	    }
