133	    public async Task<long> AddCaseAsync(long employeeMasterId, DateTime? resignDate, DateTime? lastWorkingDate,
134	        DateTime? dateOfJoining, long? departmentMasterId, long? designationMasterId, long? reportingPersonId,
135	        int? noticeDaysRequired, long? exitFormalityId, string caseNo, long userId, long companyId)
136	    {
137	        const string sql = @"
138	            INSERT INTO HR_FNFSettlement
139	                (CaseNo, EmployeeMasterID, CaseDate, ResignDate, LastWorkingDate, DateOfJoining,
140	                 DepartmentMasterID, DesignationMasterID, ReportingPersonID, NoticeDaysRequired,
141	                 ExitFormalityID, CasePriority, WorkflowStatus, CompanyMasterID, Status,
142	                 EntryUserMasterID, EntryUserDateTime, SystemName)
143	            OUTPUT INSERTED.FNFSettlementID
144	            VALUES
145	                (@CaseNo, @EmployeeMasterId, @Today, @ResignDate, @LastWorkingDate, @DateOfJoining,
146	                 @DepartmentMasterId, @DesignationMasterId, @ReportingPersonId, @NoticeDaysRequired,
147	                 @ExitFormalityId, 'Normal', 'Draft', @CompanyId, 1,
148	                 @UserId, @Now, @SystemName)";
149	
150	        return await _repo.QueryFirstOrDefaultAsync<long>(sql, new
151	        {
152	            CaseNo = caseNo, EmployeeMasterId = employeeMasterId, Today = DateTime.Today,
153	            ResignDate = resignDate, LastWorkingDate = lastWorkingDate, DateOfJoining = dateOfJoining,
154	            DepartmentMasterId = departmentMasterId, DesignationMasterId = designationMasterId,
155	            ReportingPersonId = reportingPersonId, NoticeDaysRequired = noticeDaysRequired,
156	            ExitFormalityId = exitFormalityId, CompanyId = companyId, UserId = userId,
157	            Now = DateTime.Now, SystemName = "HRMS_WEB",
158	        });
159	    }
