177	        try
178	        {
179	            const string sql = @"
180	                UPDATE HR_FNFSettlement
181	                SET    CasePriority = @CasePriority, PlannedCalcStartDate = @PlannedCalcStartDate,
182	                       PlannedSettlementDate = @PlannedSettlementDate, ActualCalcStartDate = @ActualCalcStartDate,
183	                       ApprovalTurnaroundDays = @ApprovalTurnaroundDays,
184	                       HRExecutiveUserMasterID = @HrExecutiveUserMasterId,
