191	            await _repo.ExecuteAsync(sql, new
192	            {
193	                model.CasePriority, model.PlannedCalcStartDate, model.PlannedSettlementDate,
194	                model.ActualCalcStartDate, model.ApprovalTurnaroundDays, model.HrExecutiveUserMasterId,
