292	    public async Task RecordAcceptanceAsync(long caseId, string acceptanceResult, string? remarks)
293	    {
294	        await _tx.BeginTransactionAsync();
295	        try
296	        {
297	            const string sql = @"
298	                UPDATE HR_FNFSettlement
299	                SET    AcceptanceResult = @Result, AcceptanceRemarks = @Remarks,
300	                       AcceptedOn = ISNULL(AcceptedOn, @Now),
301	                       StatementSharedOn = ISNULL(StatementSharedOn, @Now)
302	                WHERE  FNFSettlementID = @Id";
303	            await _repo.ExecuteAsync(sql, new { Result = acceptanceResult, Remarks = remarks, Now = DateTime.Now, Id = caseId });
304	            await _tx.CommitAsync();
