 70	                                 AND f.Status = 1 AND f.WorkflowStatus <> 'Cancelled')";
 71	
 72	        if (requireExitFormality)
 73	        {
 74	            sql += @"
 75	              AND  EXISTS (SELECT 1 FROM HR_ExitFormality x
 76	                          WHERE x.EmployeeMasterID = em.EmployeeMasterID AND x.Status = 1 AND x.IsComplete = 1)";
