 83	    public async Task<(DateTime? ResignDate, DateTime? DateOfLeft, DateTime? DateOfJoining, long? DepartmentMasterId,
 84	        long? DesignationMasterId, long? ReportingPersonId, int? NoticePeriodDays, long? ExitFormalityId)?>
 85	        GetEmployeeSnapshotAsync(long employeeMasterId, long companyMasterId)
 86	    {
 87	        // NoticePeriodDays does not exist on HR_EmployeeMaster. The column is NoticePeriod, and it
 88	        // is nvarchar free text - so it holds "30" on some tenants and "1 Month" or nothing on
 89	        // others. TRY_CONVERT yields the number when it is one and NULL when it is not, which is
 90	        // exactly what an int? notice period should be: a value, or "not recorded". Reading it
 91	        // raw threw "Invalid column name 'NoticePeriodDays'" and broke the whole MakeCase handoff
 92	        // from Exit Formality into settlement.
 93	        // TRY_CONVERT is SQL 2012+, so this stays 2014-safe.
 94	        const string sql = @"
 95	            SELECT em.ResignDate, em.DateOfLeft, em.DateOfJoining, em.DepartmentMasterID, em.DesignationMasterID,
 96	                   em.ReportingPersonID,
 97	                   TRY_CONVERT(int, LTRIM(RTRIM(em.NoticePeriod))) AS NoticePeriodDays,
 98	                   (SELECT TOP 1 x.ExitFormalityID FROM HR_ExitFormality x
 99	                    WHERE x.EmployeeMasterID = em.EmployeeMasterID AND x.Status = 1
100	                    ORDER BY x.ExitFormalityID DESC) AS ExitFormalityId
101	            FROM   HR_EmployeeMaster em
102	            WHERE  em.EmployeeMasterID = @EmployeeMasterId AND em.CompanyMasterID = @CompanyMasterId";
103	
104	        var row = await _repo.QueryFirstOrDefaultAsync<EmployeeSnapshotRow>(sql,
105	            new { EmployeeMasterId = employeeMasterId, CompanyMasterId = companyMasterId });
106	        return row == null ? null : (row.ResignDate, row.DateOfLeft, row.DateOfJoining, row.DepartmentMasterId,
107	            row.DesignationMasterId, row.ReportingPersonId, row.NoticePeriodDays, row.ExitFormalityId);
108	    }
