311	    public async Task UpsertCheckAsync(long caseId, string checkKind, string checkCode, string checkName,
312	        bool isRequired, string? policyStandard, string? actualValue, int sortOrder)
313	    {
314	        await _tx.BeginTransactionAsync();
315	        try
316	        {
317	            const string sql = @"
318	                MERGE HR_FNFCheck AS target
319	                USING (SELECT @CaseId AS FNFSettlementID, @CheckKind AS CheckKind, @CheckCode AS CheckCode) AS src
320	                  ON  target.FNFSettlementID = src.FNFSettlementID AND target.CheckKind = src.CheckKind
321	                  AND target.CheckCode = src.CheckCode
322	                WHEN MATCHED THEN
323	                    -- Result and Remarks are deliberately untouched: re-seeding refreshes the
324	                    -- figures a check is about, it does not un-answer it. CheckName IS refreshed
325	                    -- so a corrected caption reaches cases that already exist.
326	                    UPDATE SET CheckName = @CheckName, PolicyStandard = @PolicyStandard, ActualValue = @ActualValue
327	                WHEN NOT MATCHED THEN
328	                    INSERT (FNFSettlementID, CheckKind, CheckCode, CheckName, IsRequired,
329	                            PolicyStandard, ActualValue, SortOrder)
330	                    VALUES (@CaseId, @CheckKind, @CheckCode, @CheckName, @IsRequired,
331	                            @PolicyStandard, @ActualValue, @SortOrder);";
332	
333	            await _repo.ExecuteAsync(sql, new
334	            {
335	                CaseId = caseId, CheckKind = checkKind, CheckCode = checkCode, CheckName = checkName,
336	                IsRequired = isRequired, PolicyStandard = policyStandard, ActualValue = actualValue, SortOrder = sortOrder,
337	            });
338	            await _tx.CommitAsync();
339	        }
340	        catch { await _tx.RollbackAsync(); throw; }
