777	    public async Task UpsertAdditionalHeadAsync(long employeeMasterId, long headId, decimal amount, string remarks,
778	        int month, int year, long categoryMasterId, long branchMasterId)
779	    {
780	        await _tx.BeginTransactionAsync();
781	        try
782	        {
783	            const string sql = @"
784	                MERGE HR_SalaryAdditionalHead AS target
785	                USING (SELECT @EmployeeMasterId AS EmployeeMasterID, @HeadId AS SalaryHeadMasterID,
786	                              @Month AS AttendMonth, @Year AS AttendYear,
787	                              @CategoryMasterId AS CategoryMasterID, @BranchMasterId AS BranchMasterID) AS src
788	                  ON  target.EmployeeMasterID = src.EmployeeMasterID AND target.SalaryHeadMasterID = src.SalaryHeadMasterID
789	                  AND target.AttendMonth = src.AttendMonth AND target.AttendYear = src.AttendYear
790	                  AND target.CategoryMasterID = src.CategoryMasterID AND target.BranchMasterID = src.BranchMasterID
791	                WHEN MATCHED THEN
792	                    UPDATE SET Amount = @Amount, Remarks = @Remarks, EditUserMasterID = @UserId, EditUserDateTime = @Now
793	                WHEN NOT MATCHED THEN
794	                    INSERT (SalaryHeadMasterID, AccountHeadCode, EmployeeMasterID, Amount, Remarks, AttendMonth,
795	                            AttendYear, CategoryMasterID, BranchMasterID, EntryUserMasterID, EntryUserDateTime, SystemName)
796	                    VALUES (@HeadId, '', @EmployeeMasterId, @Amount, @Remarks, @Month, @Year,
797	                            @CategoryMasterId, @BranchMasterId, @UserId, @Now, @SystemName);";
798	
799	            await _repo.ExecuteAsync(sql, new
800	            {
801	                EmployeeMasterId = employeeMasterId, HeadId = headId, Amount = amount, Remarks = remarks,
802	                Month = (decimal)month, Year = (decimal)year, CategoryMasterId = categoryMasterId,
