748	    public async Task EnsureEmployeeHeadAsync(long employeeMasterId, long headId, long categoryMasterId, long branchMasterId, long companyMasterId)
749	    {
750	        await _tx.BeginTransactionAsync();
751	        try
752	        {
753	            // 'Manual' is LOAD-BEARING: the payroll engine's pro-rata scaling exempts only
754	            // 'Manual' and 'FixPerMonthDay' rows - any other AmountCalculation value would
755	            // silently scale this figure down for someone leaving mid-month.
756	            const string sql = @"
757	                IF NOT EXISTS (SELECT 1 FROM HR_EmployeeWiseSalaryHead
758	                               WHERE EmployeeMasterID = @EmployeeMasterId AND SalaryHeadMasterID = @HeadId
759	                                 AND CategoryMasterID = @CategoryMasterId AND BranchMasterID = @BranchMasterId)
760	                INSERT INTO HR_EmployeeWiseSalaryHead
761	                    (SalaryHeadMasterID, AccountHeadCode, [Add/Deduct], Amount, AmountCalculation, AllowEdit,
762	                     EmployeeMasterID, CategoryMasterID, BranchMasterID, CompanyMasterID, Status)
763	                VALUES
764	                    (@HeadId, '', 'Add', 0, 'Manual', 1,
765	                     @EmployeeMasterId, @CategoryMasterId, @BranchMasterId, @CompanyMasterId, 1)";
766	
767	            await _repo.ExecuteAsync(sql, new
768	            {
769	                EmployeeMasterId = employeeMasterId, HeadId = headId, CategoryMasterId = categoryMasterId,
770	                BranchMasterId = branchMasterId, CompanyMasterId = companyMasterId,
771	            });
772	            await _tx.CommitAsync();
773	        }
774	        catch { await _tx.RollbackAsync(); throw; }
775	    }
