    const string sql = @"
        SELECT TOP 1 F.*,
               LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FatherName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.LastName)),''), '')) AS EmployeeName,
               ISNULL(EM.Code, '') AS EmployeeCode
        FROM   dbo.HR_FNFSettlement F
        LEFT   JOIN dbo.HR_EmployeeMaster EM ON EM.EmployeeMasterID = F.EmployeeMasterID
        WHERE  F.EmployeeMasterID = @Emp
          AND  F.Status = 1
          AND  F.WorkflowStatus IN (@Approved, @Paid)
        ORDER  BY F.FNFSettlementID DESC";

    DataRow row = null;
